window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-2/pbe","titre":"Pratique fondée sur les preuves","sources":[{"t":"Références bibliographiques et checklists","q":"annexes-references-bibliographiques/quiz.html","f":"annexes-references-bibliographiques/fiche.html"},{"t":"Science, méthode scientifique et questions cliniques","q":"cours-01-science-et-questions-cliniques/quiz.html","f":"cours-01-science-et-questions-cliniques/fiche.html"},{"t":"Les étapes du processus de recherche","q":"cours-03-etapes-du-processus-de-recherche/quiz.html","f":"cours-03-etapes-du-processus-de-recherche/fiche.html"},{"t":"Types d'études : les études primaires","q":"cours-04-etudes-primaires/quiz.html","f":"cours-04-etudes-primaires/fiche.html"},{"t":"Les études secondaires","q":"cours-05-etudes-secondaires/quiz.html","f":"cours-05-etudes-secondaires/fiche.html"},{"t":"Méthodes d'évaluation des résultats et validation d'instruments","q":"cours-06-methodes-evaluation-et-validation/quiz.html","f":"cours-06-methodes-evaluation-et-validation/fiche.html"},{"t":"Pratique fondée sur l'évidence et pratique informée par l'évidence","q":"cours-08-pbe-et-pie/quiz.html","f":"cours-08-pbe-et-pie/fiche.html"},{"t":"Statistiques et biostatistique","q":"cours-09-statistiques/quiz.html","f":"cours-09-statistiques/fiche.html"}],"questions":[{"q":"Quelle checklist s'applique au rapport d'un essai contrôlé randomisé ?","o":["CONSORT","STROBE","PRISMA","CARE"],"r":0,"e":"CONSORT est la checklist de référence pour rapporter un essai clinique randomisé.","s":0},{"q":"Quelle checklist s'applique aux études observationnelles ?","o":["CONSORT","STROBE","SQUIRE","AGREE"],"r":1,"e":"STROBE concerne les études observationnelles : cohorte, cas-témoins et transversales.","s":0},{"q":"Quelle checklist s'applique aux revues systématiques et méta-analyses ?","o":["PRISMA","CONSORT","CARE","TREND"],"r":0,"e":"PRISMA 2020, avec sa checklist et son diagramme de flux, sert à rapporter les revues systématiques et méta-analyses.","s":0},{"q":"Quelle checklist s'applique aux rapports de cas cliniques ?","o":["STROBE","CARE","SQUIRE","AGREE"],"r":1,"e":"CARE structure le rapport de cas clinique : informations du patient, chronologie, examens, interventions, résultats, perspective du patient et consentement.","s":0},{"q":"Quelle checklist concerne les études d'intervention NON randomisées ?","o":["CONSORT","TREND","PRISMA","COSMIN"],"r":1,"e":"TREND comble l'angle mort de CONSORT pour les études d'intervention non randomisées.","s":0},{"q":"Quelle checklist concerne les études d'amélioration de la qualité des soins ?","o":["SQUIRE 2.0","AGREE","STROBE","CARE"],"r":0,"e":"SQUIRE 2.0 sert à rapporter les études d'amélioration de la qualité : contexte, intervention, mesures de processus et de résultat.","s":0},{"q":"À quoi sert l'outil AGREE ?","o":["À évaluer la qualité méthodologique d'une guideline","À rapporter un essai randomisé","À sélectionner un instrument de mesure","À enregistrer un protocole de revue"],"r":0,"e":"AGREE évalue la qualité méthodologique d'une norme d'orientation clinique : champ, participation des parties prenantes, rigueur d'élaboration, clarté, applicabilité, indépendance éditoriale.","s":0},{"q":"Que contient le diagramme de flux PRISMA ?","o":["Les étapes de sélection : études identifiées, filtrées, éligibles et incluses","Le calendrier de l'étude","La répartition des participants entre groupes","La courbe des résultats"],"r":0,"e":"Le diagramme de flux PRISMA retrace la sélection : identifiés, filtrés, éligibles, inclus, avec les motifs d'exclusion.","s":0},{"q":"À quoi sert la guideline COSMIN ?","o":["À rapporter un essai randomisé","À guider la sélection d'instruments de mesure des résultats pour un Core Outcome Set","À adapter une échelle à une autre culture","À enregistrer une revue systématique"],"r":1,"e":"COSMIN est la guideline de sélection des instruments de mesure des résultats, notamment pour constituer un Core Outcome Set.","s":0},{"q":"Combien d'étapes compte le processus d'adaptation transculturelle de Beaton et al. (2000) ?","o":["3","4","6","9"],"r":2,"e":"Le processus compte 6 étapes : traduction, synthèse, rétrotraduction, comité d'experts, pré-test et envoi du matériel aux auteurs originaux.","s":0},{"q":"Quels sont les trois critères obligatoires de l'adaptation transculturelle ?","o":["Équivalence conceptuelle, équivalence sémantique et propriétés psychométriques","Traduction, rétrotraduction et publication","Validité, fiabilité et coût","Langue, culture et contexte"],"r":0,"e":"Les critères obligatoires sont l'équivalence conceptuelle, l'équivalence sémantique et les propriétés psychométriques (validité, fiabilité).","s":0},{"q":"Combien d'étapes compte la méthodologie d'une scoping review ?","o":["3","5","6","9"],"r":1,"e":"La scoping review suit 5 étapes : identifier la question, définir la stratégie de recherche, sélectionner les études, cartographier l'information et décrire sommairement les résultats.","s":0},{"q":"Quelle différence fondamentale sépare scoping review et revue systématique ?","o":["La scoping review cartographie et n'évalue pas la qualité, la revue systématique répond à une question ciblée et évalue le risque de biais","La scoping review est plus longue à réaliser","La revue systématique ne définit pas de critères d'éligibilité","Aucune : les termes sont interchangeables"],"r":0,"e":"La scoping review cartographie un sujet large sans évaluer la qualité des études ; la revue systématique répond à une question ciblée et évalue la qualité méthodologique et le risque de biais.","s":0},{"q":"Quel rôle préliminaire peut jouer une scoping review ?","o":["Remplacer définitivement la revue systématique","Identifier la faisabilité ou la pertinence d'une revue systématique et affiner la question","Fournir une méta-analyse rapide","Valider un instrument de mesure"],"r":1,"e":"La scoping review peut être un exercice préliminaire à la revue systématique, qui en affine la question.","s":0},{"q":"Sur quelle plateforme enregistre-t-on le titre d'une revue systématique ?","o":["PROSPERO","PRISMA","Rayyan","COMET"],"r":0,"e":"L'enregistrement du titre d'une revue systématique se fait sur PROSPERO.","s":0},{"q":"Que signifie le A de la grille FAITH ?","o":["Analyser les statistiques","Ont-ils évalué les études individuellement, en utilisant le RAMBOMAN","Appliquer les résultats","Accepter les conclusions"],"r":1,"e":"Le A de FAITH demande si les auteurs ont évalué les études individuellement, ce qui renvoie à l'usage du RAMBOMAN.","s":0},{"q":"Que couvre l'acronyme RAMBOMAN ?","o":["Recrutement, Allocation, Maintien, aveuglement (Blinding), Objectif, Mesures, ANalyse","Revue, Article, Méthode, Biais, Outcome, Mesure, Analyse","Randomisation, Aveuglement, Mesure, Biais, Objectif, Méthode, Analyse","Rapport, Adaptation, Méthode, Bilan, Objectif, Modèle, Analyse"],"r":0,"e":"RAMBOMAN = Recrutement, Allocation, Maintien, Aveuglement/dissimulation, Objectif, Mesures, ANalyse.","s":0},{"q":"Que change la « nouvelle pyramide » de l'évidence ?","o":["Elle supprime les études observationnelles","Elle fait des revues systématiques la lentille à travers laquelle on lit les études primaires, avec des frontières moins rigides entre étages","Elle place les avis d'experts au sommet","Elle classe les études par date de publication"],"r":1,"e":"Dans la nouvelle pyramide, les revues systématiques ne sont plus un simple étage supérieur mais la lentille de lecture des études primaires, et les frontières entre niveaux deviennent moins rigides.","s":0},{"q":"Quel est l'apport principal des données de vie réelle ?","o":["Une validité interne élevée","Une validité externe élevée, permettant de répondre à la question de l'effectivité","Une randomisation plus rigoureuse","Un coût plus élevé"],"r":1,"e":"Les real world studies ont une validité externe élevée et une validité interne basse : elles répondent à la question de l'effectivité, là où les ECR répondent à l'efficacité.","s":0},{"q":"Quelle phrase résume le rapport entre ECR et données de vie réelle ?","o":["L'efficacité ne se traduit pas toujours en effectivité","Les ECR sont toujours supérieurs","Les données de vie réelle remplacent les ECR","Les deux mesurent la même chose"],"r":0,"e":"Le cours conclut que l'efficacité, propriété intrinsèque démontrée par les ECR, ne se traduit pas toujours en effectivité, mesurée par les real world studies.","s":0},{"q":"Quelle est la différence entre PREM et PROM ?","o":["Les PREM mesurent l'expérience des soins, les PROM les résultats de santé","Les PREM sont remplis par le clinicien, les PROM par le patient","Les PREM sont génériques, les PROM spécifiques","Il n'y a aucune différence"],"r":0,"e":"Les PREM (Patient-Reported Experience Measures) évaluent la satisfaction et la qualité de l'expérience ; les PROM (Patient-Reported Outcome Measures) évaluent les résultats sur la santé, comme le SF-36 ou l'EuroQol EQ-5D.","s":0},{"q":"Lequel de ces instruments est cité comme exemple de PROM ?","o":["Le SF-36","Le Hospital Consumer Assessment of Health Care Providers and Systems","L'AGREE","Le CONSORT"],"r":0,"e":"Le SF-36 et l'EuroQol EQ-5D sont des exemples de PROM.","s":0},{"q":"Quelle stratégie de question la scoping review sur les priorités de recherche illustre-t-elle ?","o":["PICOT","PCC (Population / Concept / Contexte)","PECOT","POT"],"r":1,"e":"Les scoping reviews utilisent la stratégie PCC : Population, Concept, Contexte.","s":0},{"q":"Quelle priorité arrive en tête des consensus de recherche en kinésithérapie au Portugal ?","o":["Le coût-efficacité","La qualité","Le développement professionnel","La prestation de services"],"r":0,"e":"Les priorités les plus consensuelles sont, dans l'ordre présenté : coût-efficacité, prestation de services et éducation, développement professionnel, qualité.","s":0},{"q":"Pourquoi l'adhésion au traitement est-elle un enjeu de PBE ?","o":["Parce qu'elle conditionne l'effectivité, c'est-à-dire le passage de l'essai à la pratique","Parce qu'elle mesure la validité interne","Parce qu'elle permet la randomisation","Parce qu'elle remplace le consentement éclairé"],"r":0,"e":"L'adhésion est le pont entre l'efficacité démontrée en essai et le résultat obtenu en pratique : c'est un déterminant majeur de l'effectivité.","s":0},{"q":"À quelle catégorie de résultats se rattachent les effets de l'exercice sur l'anxiété et la dépression ?","o":["Aux résultats cliniques","Aux résultats humanistiques","Aux résultats économiques","Aux résultats méthodologiques"],"r":1,"e":"Qualité de vie et symptômes anxio-dépressifs relèvent des résultats humanistiques, qui donnent la perspective des patients.","s":0},{"q":"Quels outils servent à évaluer la qualité et le risque de biais d'une revue systématique ?","o":["AMSTAR et CASP","CONSORT et STROBE","COSMIN et Beaton","Rayyan et JANE"],"r":0,"e":"AMSTAR et la CASP Checklist for Systematic Review servent à évaluer la qualité et le risque de biais des revues systématiques.","s":0},{"q":"À quoi sert l'outil Rayyan ?","o":["À gérer la sélection des études d'une revue","À calculer une méta-analyse","À enregistrer un protocole","À choisir une revue de publication"],"r":0,"e":"Rayyan est un outil d'aide à la sélection des études dans le processus de revue.","s":0},{"q":"À quoi sert l'outil JANE ?","o":["À détecter les essais problématiques","À trouver, à partir du titre et des mots-clés, les meilleures revues où soumettre une publication","À évaluer la qualité d'une guideline","À adapter une échelle"],"r":1,"e":"JANE fournit, avec le titre et les mots-clés, les meilleures revues auxquelles soumettre une publication.","s":0},{"q":"À quoi sert INSPECT-SR ?","o":["À détecter les essais cliniques problématiques qui distordent l'évidence dans les revues systématiques","À calculer la taille d'échantillon","À évaluer les propriétés psychométriques","À rapporter une étude observationnelle"],"r":0,"e":"INSPECT-SR (INveStigating ProblEmatic Clinical Trials in Systematic Reviews) détecte les essais problématiques qui distordent l'évidence.","s":0},{"q":"La checklist CONSORT impose notamment de rapporter :","o":["Le flux des participants, la génération de la séquence d'allocation, l'allocation concealment et l'aveuglement","Le contrôle des facteurs de confusion","La perspective du patient","Les mesures de processus"],"r":0,"e":"Elle s'applique aux essais contrôlés randomisés et exige aussi le rapport des outcomes primaires et secondaires ainsi que des analyses.","s":0},{"q":"La checklist STROBE impose de rapporter notamment :","o":["L'aveuglement","Le design, le cadre, les participants, les variables, les sources de données et le contrôle des facteurs de confusion","Le diagramme de flux de sélection","La rigueur d'élaboration"],"r":1,"e":"Elle couvre les études observationnelles : cohortes, cas-témoins et transversales. La taille d'échantillon doit également y figurer.","s":0},{"q":"TREND vient combler l'angle mort de CONSORT pour :","o":["Les revues systématiques","Les études d'intervention non randomisées, notamment comportementales","Les cas cliniques","Les guidelines"],"r":1,"e":"Sans randomisation, les garanties de CONSORT ne s'appliquent pas, mais l'intervention délibérée exige tout de même un cadre de rapport rigoureux.","s":0},{"q":"La checklist CARE demande de structurer un cas clinique en incluant :","o":["Les informations du patient, la chronologie, les examens, les interventions, les résultats, la perspective du patient et le consentement","La stratégie de recherche","L'évaluation du risque de biais","Les mesures de processus"],"r":0,"e":"Le rapport de cas correspond à un niveau d'évidence bas : type V dans la classification Cochrane, niveau 3 dans celle de JAMA.","s":0},{"q":"SQUIRE 2.0 s'applique aux études :","o":["Randomisées","D'amélioration de la qualité des soins","Observationnelles","De validation d'instruments"],"r":1,"e":"Elle impose de rapporter le contexte, l'intervention d'amélioration, et les mesures de processus comme de résultat.","s":0},{"q":"L'outil AGREE évalue la qualité méthodologique d'une guideline sur des domaines incluant :","o":["Le champ, la participation des parties prenantes, la rigueur d'élaboration, la clarté, l'applicabilité et l'indépendance éditoriale","La taille de l'échantillon","Le risque de biais des essais inclus","La validité transculturelle"],"r":0,"e":"L'indépendance éditoriale est un domaine décisif : une recommandation rédigée sans déclaration de conflits d'intérêts perd en crédibilité.","s":0},{"q":"Le réflexe recommandé avant de lire un article est :","o":["De lire d'abord la conclusion","D'identifier son design, puis de prendre la checklist correspondante et de vérifier ce que l'article ne rapporte pas","De vérifier le facteur d'impact de la revue","De consulter le nombre de citations"],"r":1,"e":"Le cours le formule ainsi : ce qui manque est souvent plus informatif que ce qui est écrit.","s":0},{"q":"Dans la méthode de Beaton, la rétrotraduction doit être réalisée par des traducteurs :","o":["Spécialistes du domaine de la santé","Aveugles à la version originale et extérieurs au domaine de la santé","Membres du comité d'experts","Auteurs de l'instrument"],"r":1,"e":"Cette double condition évite qu'ils reconstituent l'original de mémoire ou par connaissance du jargon, ce qui masquerait les écarts de sens.","s":0},{"q":"La méthodologie de la scoping review comporte :","o":["3 étapes","5 étapes","6 étapes","9 étapes"],"r":1,"e":"Identifier la question, définir la stratégie de recherche, sélectionner les études, cartographier l'information, décrire sommairement les résultats.","s":0},{"q":"Le F de la grille FAITH pose la question :","o":["Ont-ils trouvé la majorité des études ?","Les ont-ils évaluées individuellement ?","Que veulent dire les résultats ?","Sont-ils hétérogènes ?"],"r":0,"e":"A pour l'évaluation individuelle via RAMBOMAN, I pour l'inclusion des seules études de haute qualité, T pour le sens des résultats, H pour l'hétérogénéité.","s":0},{"q":"Le H de la grille FAITH interroge :","o":["L'exhaustivité de la recherche","L'hétérogénéité des résultats","L'honnêteté des auteurs","L'applicabilité clinique"],"r":1,"e":"Une hétérogénéité forte interdit souvent de combiner les études : le résultat global perdrait toute signification clinique.","s":0},{"q":"La nouvelle pyramide de l'évidence modifie le modèle classique en posant que :","o":["Les revues systématiques disparaissent","Les revues systématiques sont la lentille à travers laquelle on lit les études primaires, et les frontières entre étages deviennent ondulées","Les essais randomisés passent au sommet","Les opinions d'experts remontent"],"r":1,"e":"Conséquence pratique : un essai randomisé mal conduit peut valoir moins qu'une cohorte rigoureuse. La qualité de réalisation compte autant que le design.","s":0},{"q":"Les données de vie réelle répondent principalement à la question :","o":["De l'efficacité","De l'effectivité","Du coût","De la sécurité"],"r":1,"e":"Les essais contrôlés randomisés, à validité interne élevée, répondent à l'efficacité. La formule du cours : l'efficacité ne se traduit pas toujours en effectivité.","s":0},{"q":"Parmi les priorités de recherche les plus consensuelles identifiées chez les kinésithérapeutes portugais et les patients figure :","o":["Le coût-efficacité","La biomécanique","L'imagerie","La pharmacologie"],"r":0,"e":"S'y ajoutent la prestation de services et l'éducation, le développement professionnel et la qualité. L'étude illustre l'usage de la stratégie PCC.","s":0},{"q":"L'adhésion au traitement est présentée comme :","o":["Un facteur secondaire","Le pont entre l'efficacité démontrée en essai et le résultat obtenu en cabinet","Un problème purement éducatif","Un indicateur économique"],"r":1,"e":"C'est un déterminant majeur de l'effectivité, à relier aux résultats humanistiques et au contexte social de la définition de l'APTA.","s":0},{"q":"L'outil JANE sert à :","o":["Enregistrer une revue systématique","Trouver la revue où soumettre, à partir du titre et des mots-clés","Évaluer le risque de biais","Gérer la sélection des études"],"r":1,"e":"PROSPERO enregistre les titres de revues systématiques, Rayyan gère la sélection, AMSTAR et CASP évaluent la qualité.","s":0},{"q":"INSPECT-SR a pour fonction :","o":["De détecter les essais problématiques qui distordent l'évidence","De rédiger les protocoles","D'analyser les données","De traduire les échelles"],"r":0,"e":"Des essais fabriqués ou gravement défaillants intégrés à une méta-analyse peuvent en inverser la conclusion : les repérer est devenu un enjeu méthodologique.","s":0},{"q":"G-I-N et NICE sont des ressources permettant de trouver :","o":["Des revues systématiques","Des bases de données de guidelines","Des instruments de mesure","Des essais en cours"],"r":1,"e":"COMET et ICHOM concernent les Core Outcome Sets et les mesures centrées patient ; Cochrane les revues systématiques de référence.","s":0},{"q":"Le tableau de correspondance à connaître associe « instrument de mesure » à :","o":["PRISMA","COSMIN","Beaton","AGREE"],"r":1,"e":"Et « traduction d'échelle » à Beaton. Le tableau complet couvre neuf correspondances, du design à la checklist qui lui convient.","s":0},{"q":"L'étude sur les effets physiologiques de l'exercice sur l'anxiété et la dépression illustre :","o":["Un outcome clinique","Un outcome humanistique mesuré par des PROM","Un outcome économique","Une étude méthodologique"],"r":1,"e":"Elle converge avec le traitement non médicamenteux des troubles anxieux et du stress abordé en Physiopathologie II.","s":0},{"q":"Comment le cours définit-il la science ?","o":["Un ensemble d'opinions partagées par les experts","Un ensemble de connaissances humaines acquises par la découverte et l'explication des lois objectives qui régissent les phénomènes","Une accumulation de données sans interprétation","Une croyance validée par la tradition"],"r":1,"e":"La science est l'ensemble des connaissances humaines à propos de la nature, de la société et de la pensée, acquises par la découverte et l'explication des lois objectives qui régissent les phénomènes.","s":1},{"q":"Quel est le point de départ de la démarche scientifique selon le cours ?","o":["Le besoin des personnes de résoudre les problèmes du quotidien","La volonté de publier","Le financement de la recherche","La curiosité des universités"],"r":0,"e":"Le cours part du besoin des personnes de résoudre les problèmes du quotidien.","s":1},{"q":"Qu'est-ce que la méthode scientifique ?","o":["Une liste de publications de référence","Un système de règles et de processus sur lequel se fonde la recherche","Une technique statistique particulière","Un protocole de soin standardisé"],"r":1,"e":"La méthode scientifique consiste en un système de règles et de processus sur lequel se fonde la recherche.","s":1},{"q":"Quels sont les quatre caractères de la méthode scientifique ?","o":["Systématique, contrôlé, empirique et critique","Rapide, économique, reproductible et publiable","Qualitatif, quantitatif, mixte et narratif","Descriptif, analytique, prédictif et prescriptif"],"r":0,"e":"La méthode scientifique est systématique, contrôlée, empirique et critique ; c'est la forme la plus rigoureuse d'acquisition de nouvelles connaissances.","s":1},{"q":"Que signifie le caractère « systématique » de la méthode scientifique ?","o":["Qu'elle utilise toujours les mêmes tests statistiques","Qu'elle suit une séquence logique d'étapes, avec ordre et discipline, pour assurer la fiabilité","Qu'elle est systématiquement publiée","Qu'elle s'applique à tous les domaines"],"r":1,"e":"Le caractère systématique implique une séquence logique d'étapes, avec ordre et discipline pour assurer la fiabilité.","s":1},{"q":"Que signifie le caractère « contrôlé » de la méthode scientifique ?","o":["Qu'un comité contrôle le chercheur","Qu'on contrôle l'impact de facteurs externes et d'influences non liés aux variables analysées","Que les données sont vérifiées deux fois","Que l'étude est financée publiquement"],"r":1,"e":"Le caractère contrôlé signifie qu'on contrôle l'impact des facteurs externes et des influences qui ne sont pas liés aux variables analysées.","s":1},{"q":"Que signifie le caractère « empirique » ?","o":["Que les conclusions résultent de l'observation directe, fondées sur la réalité et l'évidence observée","Que la recherche se fonde sur l'expérience personnelle du chercheur","Que les résultats sont approximatifs","Que la méthode est purement théorique"],"r":0,"e":"Le caractère empirique signifie que les conclusions tirées résultent de l'observation directe, fondées sur la réalité et l'évidence observée.","s":1},{"q":"Que signifie le caractère « critique » de la méthode scientifique ?","o":["Que le chercheur doit critiquer les travaux antérieurs","Que le chercheur doit soumettre ses résultats aux autres chercheurs, l'information devant être validée et corrigée","Que la recherche porte sur des situations critiques","Que les limites doivent être signalées"],"r":1,"e":"Le caractère critique impose que le chercheur soumette ses résultats aux autres chercheurs : l'information doit être validée et corrigée.","s":1},{"q":"Quelle est la première étape du processus de recherche ?","o":["Le choix de la méthode statistique","La question","La sélection de l'échantillon","La demande de financement"],"r":1,"e":"La question est la première étape et est essentielle pour définir le processus de la recherche, c'est-à-dire le parcours que nous allons faire.","s":1},{"q":"À quel type de question correspond « Que faire dans cette situation ou ce problème ? »","o":["Diagnostic","Intervention ou traitement","Pronostic","Fréquence"],"r":1,"e":"« Que faire dans cette situation ou ce problème ? » correspond à une question d'intervention ou de traitement.","s":1},{"q":"À quel type de question correspond « Quelle est la cause de la survenue du problème ? »","o":["Étiologie / risque","Pronostic","Diagnostic","Expériences des patients"],"r":0,"e":"Cette formulation correspond à une question d'étiologie ou de risque, c'est-à-dire de cause de la maladie.","s":1},{"q":"À quel type de question correspond « Ce patient a-t-il le problème ou cette situation ? »","o":["Fréquence","Diagnostic","Intervention","Étiologie"],"r":1,"e":"« Ce patient a-t-il le problème ou cette situation ? » est une question de diagnostic.","s":1},{"q":"À quel type de question correspond « Cette situation ou ce problème est-il fréquent ? »","o":["Pronostic","Fréquence du problème","Diagnostic","Étiologie"],"r":1,"e":"Cette formulation correspond à une question de fréquence du problème.","s":1},{"q":"À quel type de question correspond « Que pense le patient de sa situation ou de son problème ? »","o":["Expériences des patients","Pronostic","Intervention","Diagnostic"],"r":0,"e":"Cette question relève des expériences des patients, domaine des études qualitatives.","s":1},{"q":"Quel type de question est « L'aspirine est-elle efficace dans le rhume ? »","o":["Diagnostic","Intervention","Fréquence","Étiologie"],"r":1,"e":"C'est une question d'intervention, puisqu'elle porte sur l'efficacité d'un traitement.","s":1},{"q":"Quel type de question est « La malaria est-elle fréquente en Indonésie ? »","o":["Fréquence","Pronostic","Étiologie","Diagnostic"],"r":0,"e":"C'est une question de fréquence du problème.","s":1},{"q":"Quel type de question est « Fumer provoque-t-il le cancer du poumon ? »","o":["Intervention","Étiologie ou risque","Diagnostic","Expériences des patients"],"r":1,"e":"C'est une question d'étiologie ou de risque, c'est-à-dire de cause du problème.","s":1},{"q":"Quel type de question est « Le test COVID est-il fiable pour les asymptomatiques ? »","o":["Diagnostic","Pronostic","Intervention","Fréquence"],"r":0,"e":"C'est une question de diagnostic, puisqu'elle porte sur la fiabilité d'un test.","s":1},{"q":"Quel type de question est « Quelles sont les maladies les plus probables comme conséquence de l'usage excessif du téléphone portable ? »","o":["Diagnostic","Pronostic ou évolution de la maladie","Intervention","Fréquence"],"r":1,"e":"C'est une question de pronostic, c'est-à-dire d'évolution de la maladie et de probabilité de survenue.","s":1},{"q":"Quels sont les deux grands paradigmes de recherche ?","o":["Descriptif et analytique","Quantitatif et qualitatif","Primaire et secondaire","Interne et externe"],"r":1,"e":"Le cours distingue le paradigme quantitatif et le paradigme qualitatif ; souvent ils se complètent.","s":1},{"q":"Quelle est la relation entre les paradigmes quantitatif et qualitatif ?","o":["Ils s'excluent mutuellement","Souvent ils se complètent","Le qualitatif est toujours supérieur","Le quantitatif remplace le qualitatif"],"r":1,"e":"Le cours indique que souvent les deux paradigmes se complètent.","s":1},{"q":"Sur quoi repose le choix entre les différents types de recherche ?","o":["Sur l'objet et l'objectif de la recherche","Sur le budget disponible","Sur les préférences du chercheur","Sur la revue visée"],"r":0,"e":"Chaque méthode comporte un certain nombre de types de recherche et le choix se fait en fonction de l'objet et de l'objectif de la recherche.","s":1},{"q":"Quelle unité précède PBE I dans le cursus ?","o":["PBE II","MTP en 1re année","Projet I","Aucune"],"r":1,"e":"Le cursus enchaîne MTP (1re année), PBE I (2e année), PBE II (3e année) puis Projet I et II (4e année).","s":1},{"q":"Quelle thématique traite de la validité interne, de la validité externe et des biais ?","o":["Thématique 1 · Évaluation et résultats","Thématique 2 · Design et types d'études","Thématique 3 · Méthodes et instruments","Thématique 4 · Partage et diffusion"],"r":1,"e":"La thématique 2 porte sur le design et les types d'études : validité interne, validité externe, biais, études primaires, secondaires et méthodologiques.","s":1},{"q":"Quelle thématique traite des propriétés psychométriques ?","o":["Thématique 1","Thématique 2","Thématique 3 · Méthodes et instruments","Thématique 4"],"r":2,"e":"La thématique 3 porte sur les méthodes et instruments : types de résultats et propriétés psychométriques.","s":1},{"q":"Dans quelle thématique figure la pyramide de l'évidence ?","o":["Thématique 4 · Partage et diffusion des résultats","Thématique 1","Thématique 2","Thématique 3"],"r":0,"e":"La thématique 4 traite du partage et de la diffusion des résultats : pyramide de l'évidence, pratique fondée sur l'évidence et pratique informée par l'évidence.","s":1},{"q":"Quelles études sont classées comme secondaires dans le programme ?","o":["Les études observationnelles et expérimentales","Les scoping reviews, revues systématiques, méta-analyses et guidelines","Les adaptations culturelles d'instruments","Les études de cas"],"r":1,"e":"Les études secondaires regroupent les scoping reviews, les revues systématiques, les méta-analyses et les guidelines.","s":1},{"q":"À quoi correspondent les études méthodologiques dans le programme ?","o":["Aux essais cliniques randomisés","À l'adaptation culturelle et à la validation d'instruments","Aux enquêtes de prévalence","Aux revues de la littérature"],"r":1,"e":"Les études méthodologiques concernent l'adaptation culturelle et la validation d'instruments.","s":1},{"q":"Quelle note minimale faut-il obtenir à chaque moment d'évaluation pour être dispensé de l'examen final ?","o":["8,5","10","12","15"],"r":0,"e":"L'étudiant doit démontrer à chaque moment des connaissances équivalentes ou supérieures à une note correspondant à 8,5, et obtenir une moyenne finale égale ou supérieure à 10 points.","s":1},{"q":"Que se passe-t-il si l'étudiant a moins de 10 points en contrôle continu ?","o":["Il redouble automatiquement","Il passe un examen final écrit portant sur toute la matière, avec une pondération de 100 %","Il repasse uniquement le moment échoué","Il est dispensé"],"r":1,"e":"En dessous de 10 points en contrôle continu, l'étudiant doit passer un examen final écrit incluant toute la matière enseignée, avec une pondération de 100 %.","s":1},{"q":"Le caractère « systématique » de la méthode scientifique implique :","o":["Une séquence logique d'étapes, avec ordre et discipline pour assurer la fiabilité","Le contrôle des facteurs externes","Le recours à l'observation directe","La soumission aux pairs"],"r":0,"e":"Les trois autres caractères sont : contrôlé, empirique et critique. Chacun répond à une menace différente sur la qualité de la connaissance produite.","s":1},{"q":"Le caractère « critique » de la méthode scientifique signifie que les résultats :","o":["Sont définitifs","Sont soumis aux autres chercheurs, validés et corrigés","Doivent être négatifs","Restent confidentiels"],"r":1,"e":"C'est ce qui distingue la science d'une conviction personnelle : elle s'expose délibérément à la contestation par ses pairs.","s":1},{"q":"Le caractère « empirique » implique que les conclusions :","o":["Découlent d'un raisonnement théorique","Sont issues de l'observation directe, fondées sur la réalité et l'évidence observée","Proviennent d'un consensus d'experts","Reposent sur des modèles mathématiques"],"r":1,"e":"Le caractère contrôlé s'y ajoute : on maîtrise l'impact des facteurs externes non liés aux variables analysées.","s":1},{"q":"La science naît, selon le cours :","o":["Du hasard des découvertes","Du besoin des personnes de résoudre les problèmes du quotidien","De la curiosité pure","Des institutions universitaires"],"r":1,"e":"Elle se définit comme l'ensemble des connaissances humaines sur la nature, la société et la pensée, acquises par la découverte des lois objectives qui régissent les phénomènes.","s":1},{"q":"La méthode scientifique est décrite comme :","o":["Une hypothèse de travail","Un système de règles et de processus sur lequel se fonde la recherche, forme la plus rigoureuse d'acquisition de connaissances nouvelles","Une opinion argumentée","Un protocole administratif"],"r":1,"e":"Cette rigueur ne garantit pas la vérité de chaque résultat, mais elle rend possibles la vérification et la correction.","s":1},{"q":"La question « Ce patient a-t-il le problème ou cette condition ? » relève d'une question :","o":["D'intervention","D'étiologie","De diagnostic","De fréquence"],"r":2,"e":"Les six types : intervention ou traitement, étiologie ou risque, pronostic, diagnostic, fréquence, et expériences des patients.","s":1},{"q":"La question « Que pense le patient de sa situation ? » relève :","o":["Du pronostic","Des expériences des patients","Du diagnostic","De l'intervention"],"r":1,"e":"Ce type de question appelle typiquement un paradigme qualitatif, là où les questions d'intervention appellent un paradigme quantitatif.","s":1},{"q":"La question « La malaria est-elle fréquente en Indonésie ? » est une question :","o":["De fréquence","D'étiologie","De pronostic","De diagnostic"],"r":0,"e":"Elle appelle une étude transversale, selon la correspondance entre type de question et design vue au cours 4.","s":1},{"q":"Les deux grands paradigmes de recherche sont :","o":["Quantitatif et qualitatif","Expérimental et observationnel","Primaire et secondaire","Descriptif et analytique"],"r":0,"e":"Le cours précise qu'ils se complètent souvent et que chacun comporte plusieurs types de recherche.","s":1},{"q":"Le choix entre les différents types de recherche se fait en fonction :","o":["Des moyens disponibles","De l'objet et de l'objectif de la recherche","De la mode scientifique","Du temps imparti"],"r":1,"e":"C'est la question qui commande la méthode, et non l'inverse — principe qui traverse tout le module.","s":1},{"q":"Dans le cursus , l'unité qui précède PBE I est :","o":["Projet I","MTP, en première année","PBE II","Projet II"],"r":1,"e":"La progression complète : MTP en première année, PBE I en deuxième, PBE II en troisième, Projet I et II en quatrième.","s":1},{"q":"La thématique du programme traitant des propriétés psychométriques est :","o":["Évaluation et résultats en santé","Design et types d'études","Méthodes et instruments","Partage et diffusion des résultats"],"r":2,"e":"La pyramide de l'évidence et la PBE relèvent de la quatrième thématique ; validité, biais et types d'études de la deuxième.","s":1},{"q":"Parmi les quatre phases du processus de recherche, la phase méthodologique répond à la question :","o":["Que cherche-t-on à savoir ?","Comment allons-nous faire le voyage ?","Qu'avons-nous trouvé ?","À qui le dire ?"],"r":1,"e":"Elle couvre le design, la population, les variables, les procédures et l'analyse. La phase conceptuelle pose la question, l'empirique recueille, la quatrième diffuse.","s":1},{"q":"Le E de l'acronyme FINER signifie :","o":["Efficace","Éthique","Évaluable","Économique"],"r":1,"e":"F pour faisable, I pour intéressante, N pour nouveauté, E pour éthique, R pour relevant, c'est-à-dire pertinente pour la connaissance et la communauté.","s":1},{"q":"Le I de FINER porte sur le caractère :","o":["Innovant","Intéressant pour la communauté et les pairs","Indépendant","Interdisciplinaire"],"r":1,"e":"La nouveauté est couverte par le N, qui pose la question de ce que l'étude ajoute à la connaissance existante.","s":1},{"q":"La déclinaison PICOT ajoute à PICO :","o":["Le design d'étude","Le temps, pour les études expérimentales","Le contexte","Le concept"],"r":1,"e":"PICOS ajoute le design, PECOT substitue l'exposition à l'intervention pour les études non expérimentales, PCC vaut pour les scoping reviews.","s":1},{"q":"La déclinaison PICo, avec un o minuscule, s'applique :","o":["Aux études qualitatives, avec Population, Intérêt et Contexte","Aux revues systématiques","Aux études de prévalence","Aux essais randomisés"],"r":0,"e":"POT sert aux études de prévalence et d'incidence. Chaque déclinaison adapte la structure de la question au type d'étude envisagé.","s":1},{"q":"L'évaluation de l'unité PBE I repose sur :","o":["Un examen final unique","Deux fiches écrites individuelles obligatoires, dont la moyenne pondérée donne la note","Un travail de groupe","Un contrôle continu hebdomadaire"],"r":1,"e":"Pour être dispensé de l'examen final, il faut au moins 8,5 à chaque moment et une moyenne finale d'au moins 10.","s":1},{"q":"En dessous de 10 en contrôle continu, l'étudiant :","o":["Repasse uniquement le moment manqué","Passe un examen final écrit portant sur toute la matière, avec une pondération de 100 %","Redouble l'unité","Conserve sa meilleure note"],"r":1,"e":"La pondération de 100 % signifie que le contrôle continu ne compte plus du tout : l'examen final se substitue intégralement.","s":1},{"q":"La question de recherche est qualifiée d'étape essentielle parce que :","o":["Elle est la plus rapide à formuler","C'est elle qui définit le parcours de la recherche","Elle détermine le financement","Elle fixe la durée de l'étude"],"r":1,"e":"Le cours file la métaphore : la question définit la destination du voyage, la phase méthodologique l'itinéraire pour s'y rendre.","s":1},{"q":"Quelles sont les quatre phases du processus de recherche ?","o":["Conceptuelle, méthodologique, empirique et diffusion des résultats","Hypothèse, expérience, résultat et publication","Question, échantillon, analyse et conclusion","Théorique, pratique, statistique et éthique"],"r":0,"e":"Les quatre phases sont : 1) conceptuelle, 2) méthodologique, 3) empirique, 4) diffusion/partage des résultats.","s":2},{"q":"Que dit le cours sur l'indépendance des phases du processus ?","o":["Elles sont totalement indépendantes","Elles ne sont pas totalement indépendantes les unes des autres","Elles doivent être menées simultanément","L'ordre est indifférent"],"r":1,"e":"Le cours précise que les phases du processus ne sont pas totalement indépendantes les unes des autres.","s":2},{"q":"Que faut-il vérifier avant de commencer un projet de recherche ?","o":["Que l'étude n'existe pas encore, qu'elle est pertinente pour la kinésithérapie et qu'elle est intéressante","Que le financement est acquis","Que la revue de publication est choisie","Que l'échantillon est déjà recruté"],"r":0,"e":"Après avoir eu l'idée et avant de commencer, il faut s'assurer que l'étude n'existe pas encore, qu'elle est pertinente pour la kinésithérapie et qu'elle est intéressante.","s":2},{"q":"Que fait une revue de la littérature selon le cours ?","o":["Elle liste toutes les publications existantes sans les juger","Elle propose une approche critique, présente les résultats antérieurs, identifie les débats et suggère la méthode à utiliser","Elle remplace la collecte de données","Elle sert uniquement à trouver des références"],"r":1,"e":"La revue de la littérature est une approche critique de la littérature existante : elle présente résultats et conclusions, identifie débats et divergences, aborde problématiques et outcomes et suggère la méthode à utiliser.","s":2},{"q":"Que signifie le F de FINER ?","o":["Fiable","Faisabilité de la question en termes de participants, méthodes, temps et coûts","Fondamental","Financé"],"r":1,"e":"F correspond à Feasible : la faisabilité de la question en termes de participants, méthodes, temps, coûts, etc.","s":2},{"q":"Que signifie le N de FINER ?","o":["Nécessaire","Nouveauté : qu'est-ce que cela ajoute à la connaissance ?","Normalisé","National"],"r":1,"e":"N correspond à Novel : qu'est-ce que cela ajoute à la connaissance ?","s":2},{"q":"Que signifie le R de FINER ?","o":["Reproductible","Randomisé","Relevant, c'est-à-dire pertinente pour la connaissance et la communauté","Rigoureux"],"r":2,"e":"R correspond à Relevant : les implications sont-elles pertinentes pour la connaissance et la communauté ?","s":2},{"q":"Que signifie l'acronyme PICO ?","o":["Population, Intervention, Comparaison, Outcome","Problème, Interprétation, Contexte, Objectif","Patient, Instrument, Critère, Observation","Protocole, Inclusion, Contrôle, Objectif"],"r":0,"e":"PICO = Population/Problème, Intervention/Exposition, Comparaison/Contrôle, Outcome (mesure de résultat).","s":2},{"q":"Comment le cours décrit-il le rôle de PICO ?","o":["Une étape facultative de la rédaction","L'étape primordiale qui définit la « destination du voyage »","Une méthode d'analyse statistique","Un outil de sélection de revue"],"r":1,"e":"PICO est une étape primordiale pour tout le processus de recherche : elle définit la « destination du voyage ».","s":2},{"q":"Que représente le O de PICO ?","o":["L'objectif de l'étude","L'outcome, c'est-à-dire les variables dépendantes mesurées pour répondre au problème","L'observation clinique","L'organisation de l'étude"],"r":1,"e":"Le O désigne l'outcome : les résultats pertinents à observer, c'est-à-dire les variables dépendantes mesurées (douleur, fonctionnalité, qualité de vie, force, amplitude…).","s":2},{"q":"Quelle déclinaison de PICO s'applique aux scoping reviews ?","o":["PICOT","PECOT","PCC (Population / Concept / Contexte)","POT"],"r":2,"e":"PCC — Population, Concept, Contexte — s'applique aux scoping reviews.","s":2},{"q":"Quelle déclinaison s'applique aux études qualitatives ?","o":["PICo (Population / Intérêt / Contexte)","PICOS","POT","PECOT"],"r":0,"e":"PICo — Population/Patient/Problème, Intérêt, Contexte — s'applique aux études qualitatives.","s":2},{"q":"Quelle déclinaison s'applique aux études non expérimentales ?","o":["PICOT","PECOT","PCC","PICo"],"r":1,"e":"PECOT — Population, Exposition, Outcomes, Temps — s'applique aux études non expérimentales ; PICOT concerne les études expérimentales.","s":2},{"q":"Quelle déclinaison s'applique aux études de prévalence et d'incidence ?","o":["POT (Population / Outcomes / Temps)","PICOS","PCC","PICo"],"r":0,"e":"POT — Population, Outcomes, Temps — s'applique aux études de prévalence et d'incidence.","s":2},{"q":"Combien d'objectifs le cours recommande-t-il ?","o":["Un seul objectif au total","1 objectif général et jusqu'à environ 3 spécifiques","Au moins 5 objectifs spécifiques","Autant que de variables mesurées"],"r":1,"e":"Les objectifs doivent comprendre 1 objectif général ou primaire et jusqu'à environ 3 spécifiques ou secondaires.","s":2},{"q":"Quels verbes le cours recommande-t-il pour formuler les objectifs ?","o":["« Penser », « supposer »","« Déterminer », « évaluer »","« Prouver », « démontrer »","« Croire », « estimer »"],"r":1,"e":"Le cours recommande des verbes comme « déterminer » et « évaluer ».","s":2},{"q":"Comment le cours définit-il une population ?","o":["Un sous-ensemble de sujets tirés au sort","Le nombre total d'éléments qui possèdent des caractéristiques communes pertinentes pour l'étude","Les patients d'un service donné","Les sujets ayant accepté de participer"],"r":1,"e":"La population est le nombre total d'éléments qui possèdent des caractéristiques communes pertinentes (critères d'éligibilité) pour l'étude.","s":2},{"q":"Quelle qualité l'échantillon doit-il posséder ?","o":["Être le plus grand possible","Être représentatif : ses caractéristiques doivent se rapprocher le plus possible de la population","Être homogène en âge uniquement","Être recruté dans un seul centre"],"r":1,"e":"L'échantillon est un sous-ensemble de la population ; il doit être représentatif, ses caractéristiques devant se rapprocher le plus possible de celles de la population.","s":2},{"q":"Quelle conséquence a une grande homogénéité de l'échantillon ?","o":["Elle augmente la validité interne mais diminue le potentiel de généralisation","Elle augmente à la fois la validité interne et la généralisation","Elle diminue la validité interne","Elle n'a aucun effet sur la validité"],"r":0,"e":"Plus il y a d'homogénéité, plus grande est la validité interne, mais plus faible est le potentiel de généralisation des résultats.","s":2},{"q":"Quelle est la meilleure technique d'échantillonnage selon le cours ?","o":["L'échantillonnage de convenance","L'échantillonnage intentionnel","La randomisation","L'échantillonnage par quotas"],"r":2,"e":"Parmi les échantillons aléatoires, la randomisation est présentée comme la meilleure technique d'échantillonnage.","s":2},{"q":"Quel effet a la réduction de la marge d'erreur souhaitée ?","o":["L'échantillon devra être plus grand","L'échantillon pourra être plus petit","Cela n'a aucun effet sur la taille","Cela augmente le degré de confiance"],"r":0,"e":"Plus la marge d'erreur maximale souhaitée est petite, plus l'échantillon devra être grand.","s":2},{"q":"Que se passe-t-il quand le degré de confiance augmente ?","o":["L'intervalle de résultats possibles devient plus étroit","L'intervalle de résultats possibles au sein d'un échantillon devient plus large","La marge d'erreur disparaît","La population change"],"r":1,"e":"Plus le degré de confiance établi est élevé, plus l'intervalle de résultats possibles au sein d'un échantillon sera large ; cet intervalle se délimite en écarts-types.","s":2},{"q":"Comment définit-on la variable indépendante ?","o":["C'est le résultat ou l'effet observé","Elle peut être manipulée et explique le résultat : c'est la variable « cause »","C'est la variable mesurée en fin d'étude","C'est une variable de confusion"],"r":1,"e":"La variable indépendante peut être manipulée, elle explique le résultat (relation, cause) : c'est la variable « cause ».","s":2},{"q":"Quelles sont les trois familles de résultats en santé ?","o":["Cliniques, humanistiques et économiques","Primaires, secondaires et tertiaires","Objectifs, subjectifs et mixtes","Quantitatifs, qualitatifs et mixtes"],"r":0,"e":"Les résultats cliniques donnent la perspective des professionnels, les humanistiques celle des patients, familles et aidants, et les économiques celle du payeur et de la société.","s":2},{"q":"Quel exemple correspond à un résultat humanistique ?","o":["Le grade de force musculaire","La qualité de vie et l'intensité de la douleur","Le nombre de consultations","Le coût de l'intervention"],"r":1,"e":"Les résultats humanistiques donnent la perspective des patients : qualité de vie, intensité de la douleur.","s":2},{"q":"Quel exemple correspond à un résultat économique ?","o":["L'amplitude de mouvement","Le nombre de consultations, d'interventions, les coûts et la productivité","La qualité de vie","Le grade de force"],"r":1,"e":"Les résultats économiques comprennent le nombre de consultations, les interventions, les coûts et la productivité.","s":2},{"q":"Que sont les Core Outcomes Sets (COS) ?","o":["Des tests statistiques standardisés","Un ensemble minimal de domaines de résultats considérés fondamentaux","Des questionnaires validés dans une seule langue","Des critères d'inclusion obligatoires"],"r":1,"e":"Les Core Outcomes Sets constituent un ensemble minimal de domaines de résultats considérés fondamentaux.","s":2},{"q":"Que désignent les PROM et PREM ?","o":["Des mesures de performance réalisées par le professionnel","Des mesures rapportées par les patients : outcomes et expériences","Des dispositifs de mesure instrumentale","Des protocoles de randomisation"],"r":1,"e":"PROM et PREM sont les Patient Reported Outcome and Experience Measures, mesures rapportées par les patients : qualité de vie, intensité de la douleur.","s":2},{"q":"Quelles sont les quatre étapes de la phase empirique ?","o":["Recueillir, préparer, analyser et interpréter les données","Formuler, tester, valider et publier","Randomiser, traiter, mesurer et comparer","Lire, écrire, présenter et publier"],"r":0,"e":"La phase empirique comprend : 1) recueillir les données, 2) préparer les données en saisissant la base, 3) analyser les données, 4) interpréter les résultats.","s":2},{"q":"Quelle limite le cours fixe-t-il pour le contenu d'une diapositive ?","o":["Pas plus de 3 lignes et 10 mots par ligne","Pas plus de 6 lignes de texte et 6 mots par ligne, environ 1 minute par diapositive","Pas plus de 10 lignes, sans limite de mots","Aucune limite n'est fixée"],"r":1,"e":"Les diapositives ne doivent pas contenir plus de 6 lignes de texte ni plus de 6 mots par ligne, avec environ 1 minute par diapositive ; les diapositives ne sont pas des antisèches.","s":2},{"q":"Les vérifications préalables à tout projet de recherche portent sur le fait que l'étude :","o":["N'existe pas encore, est pertinente pour la kinésithérapie et est intéressante","Est finançable, rapide et publiable","Est simple, courte et peu coûteuse","Est approuvée par le directeur"],"r":0,"e":"Ces trois questions se posent après avoir eu l'idée et avant de s'engager : elles évitent de reproduire un travail déjà fait ou sans portée.","s":2},{"q":"La revue de la littérature, dans la phase conceptuelle :","o":["Se contente de lister les publications","Présente les résultats et conclusions antérieurs et identifie débats, divergences et questions ouvertes","Remplace l'étude","Fixe la méthodologie"],"r":1,"e":"C'est une approche critique : elle ne recense pas, elle situe le projet dans un état des savoirs et de leurs désaccords.","s":2},{"q":"Le O de PICO correspond à :","o":["L'objectif","L'outcome, c'est-à-dire la mesure de résultat","L'observation","L'organisation"],"r":1,"e":"P pour population ou problème, I pour intervention ou exposition, C pour comparaison ou contrôle, O pour outcome.","s":2},{"q":"Concernant les objectifs d'une recherche, le cours recommande :","o":["Un seul objectif global","Un objectif général et jusqu'à environ trois objectifs spécifiques","Au moins dix objectifs","Autant d'objectifs que de variables"],"r":1,"e":"Ils doivent identifier les variables, leur relation possible et la nature de la population, rester simples, et employer des verbes comme « déterminer » ou « évaluer ».","s":2},{"q":"Plus les critères d'éligibilité sont rigoureux :","o":["Plus l'échantillon est hétérogène","Plus la validité interne augmente mais plus le potentiel de généralisation diminue","Plus les deux validités augmentent","Moins l'étude est fiable"],"r":1,"e":"C'est l'arbitrage fondamental du design : contrôler pour conclure, ou ouvrir pour généraliser. On ne peut maximiser les deux à la fois.","s":2},{"q":"La variable indépendante se définit comme :","o":["L'effet observé","La cause, manipulable, qui explique le résultat","Une variable parasite","Une variable non mesurée"],"r":1,"e":"La variable dépendante est l'effet, c'est-à-dire le résultat de la variable indépendante.","s":2},{"q":"Le nombre de séances et les coûts relèvent des résultats :","o":["Cliniques","Humanistiques","Économiques","Méthodologiques"],"r":2,"e":"Ils s'apprécient dans la perspective du payeur et de la société. La productivité entre également dans cette catégorie.","s":2},{"q":"La phase empirique comporte quatre étapes :","o":["Recueillir, préparer, analyser et interpréter les données","Questionner, chercher, évaluer et appliquer","Concevoir, réaliser, publier et diffuser","Observer, mesurer, comparer et conclure"],"r":0,"e":"La préparation consiste notamment à saisir la base de données, étape souvent sous-estimée et pourtant décisive pour la qualité de l'analyse.","s":2},{"q":"Selon le cours, publier revient à :","o":["Défendre une position","Ajouter une brique de plus au mur de la connaissance","Obtenir une reconnaissance","Clore un projet"],"r":1,"e":"Les voies de diffusion citées sont la communication orale, le poster, les revues, les livres et les newsletters.","s":2},{"q":"La réduction de la marge d'erreur souhaitée a pour effet :","o":["De diminuer la taille d'échantillon nécessaire","D'augmenter la taille d'échantillon nécessaire","De n'avoir aucun effet","De réduire le niveau de confiance"],"r":1,"e":"De même, augmenter le degré de confiance exige davantage de participants : précision et certitude se paient toutes deux en effectifs.","s":2},{"q":"Une grande homogénéité de l'échantillon a pour conséquence :","o":["Une meilleure généralisation","Une validité interne renforcée au prix d'une généralisation réduite","Une perte de validité interne","Une augmentation des biais de mesure"],"r":1,"e":"C'est la conséquence directe de critères d'éligibilité rigoureux : l'échantillon ressemble de moins en moins à la population réelle.","s":2},{"q":"Les phases du processus de recherche sont décrites comme :","o":["Totalement indépendantes","Non totalement indépendantes : elles s'informent mutuellement et le chercheur revient en arrière","Strictement successives","Interchangeables"],"r":1,"e":"Découvrir en phase méthodologique qu'une variable est inmesurable oblige par exemple à reformuler la question posée en phase conceptuelle.","s":2},{"q":"Une population se définit dans ce cours comme :","o":["L'ensemble des habitants d'un pays","L'ensemble des éléments partageant les caractéristiques d'intérêt pour l'étude","Les patients d'un service","Les participants recrutés"],"r":1,"e":"L'échantillon en est un sous-ensemble, qui doit être représentatif pour autoriser l'inférence à la population entière.","s":2},{"q":"La qualité essentielle que doit posséder un échantillon est :","o":["Sa grande taille","Sa représentativité de la population","Son homogénéité parfaite","Sa disponibilité"],"r":1,"e":"Un grand échantillon non représentatif reste biaisé : la taille améliore la précision, pas la justesse.","s":2},{"q":"La meilleure technique d'échantillonnage, selon le cours, est :","o":["L'échantillonnage de convenance","L'échantillonnage aléatoire ou probabiliste","Le volontariat","La sélection par le clinicien"],"r":1,"e":"Elle seule donne à chaque élément une probabilité connue d'être sélectionné, ce qui fonde la validité de l'inférence statistique.","s":2},{"q":"La phase méthodologique couvre notamment :","o":["Le type et le design d'étude, la population et les critères d'éligibilité, l'échantillonnage, les méthodes de recueil et l'analyse","La revue de la littérature","L'interprétation des résultats","La rédaction de l'article"],"r":0,"e":"Elle définit toutes les décisions techniques avant tout recueil : c'est le moment où les biais peuvent encore être prévenus par le design.","s":2},{"q":"Les Core Outcome Sets ont pour fonction :","o":["De limiter le nombre de participants","De définir un ensemble minimal de domaines de résultats à mesurer dans les études d'un domaine donné","De standardiser les interventions","De fixer les critères d'éligibilité"],"r":1,"e":"Leur adoption rend les études comparables et rend possibles les méta-analyses, souvent empêchées par l'hétérogénéité des outcomes choisis.","s":2},{"q":"La qualité de vie et la satisfaction relèvent des résultats :","o":["Cliniques","Humanistiques","Économiques","Méthodologiques"],"r":1,"e":"Ils s'apprécient dans la perspective des patients, des familles et des aidants — celle qui compte le plus pour juger d'un bénéfice réel.","s":2},{"q":"La quatrième phase du processus de recherche correspond :","o":["À l'analyse des données","À la diffusion et au partage des résultats","À la formulation de la question","Au choix du design"],"r":1,"e":"Une recherche non diffusée n'ajoute rien à la connaissance collective : c'est le sens de l'image de la brique ajoutée au mur.","s":2},{"q":"Le F de FINER interroge la faisabilité au regard :","o":["Des participants, des méthodes, du temps et des coûts","De l'intérêt scientifique","De l'éthique","De la nouveauté"],"r":0,"e":"Un projet passionnant mais irréalisable dans les conditions disponibles échoue avant même de commencer : cette lettre vient en premier pour cette raison.","s":2},{"q":"Comment le cours définit-il la validité ?","o":["La reproductibilité d'une mesure","Le fait que les résultats reflètent la vérité et que l'étude mesure ce qui est censé être mesuré","La taille suffisante de l'échantillon","L'absence de conflit d'intérêts"],"r":1,"e":"La validité signifie que ce que je fais dans l'étude, les résultats reflètent la vérité et mesurent ce qui est censé être mesuré.","s":3},{"q":"Que désigne la validité interne ?","o":["La généralisation des résultats à la population","Le degré de fiabilité du fait que les conclusions sont valides pour l'échantillon étudié","La qualité de la revue de la littérature","Le respect du protocole éthique"],"r":1,"e":"La validité interne est le degré de fiabilité du fait que les conclusions d'une étude sont valides pour l'échantillon étudié, et la capacité d'affirmer que les résultats et la relation des variables sont réels.","s":3},{"q":"Que désigne la validité externe ?","o":["L'applicabilité des conclusions à la population et la généralisation des résultats","La rigueur du contrôle des variables","L'absence d'erreur de mesure","La comparabilité des groupes"],"r":0,"e":"La validité externe est l'applicabilité des conclusions d'une étude à la population, c'est-à-dire la généralisation des résultats.","s":3},{"q":"Par quoi la validité externe peut-elle être affectée ?","o":["Par des erreurs de sélection des participants","Par le choix du test statistique","Par la taille de l'effet","Par l'absence d'aveuglement"],"r":0,"e":"La validité externe peut être affectée par des erreurs de sélection des participants ; la validité interne, elle, par des erreurs systématiques dans la mesure ou la relation entre variables.","s":3},{"q":"Qu'est-ce qu'un biais ?","o":["Une erreur aléatoire due au hasard","Une erreur systématique, écart par rapport à la vérité, qui menace la validité interne","Une différence entre deux groupes","Une faute de calcul statistique"],"r":1,"e":"Le biais est une erreur systématique : un processus pouvant survenir à n'importe quel moment de l'étude et qui tend à produire des résultats systématiquement différents des valeurs réelles, menaçant la validité interne.","s":3},{"q":"Quels sont les trois types de biais cités ?","o":["Selection bias, measurement bias et confounding bias","Publication bias, recall bias et attrition bias","Random bias, fixed bias et mixed bias","Bias primaire, secondaire et tertiaire"],"r":0,"e":"Le cours cite le selection bias (sélection des participants), le measurement bias (mesure et recueil des données) et le confounding bias (relation entre variables).","s":3},{"q":"Qu'est-ce que la précision selon le cours ?","o":["Une erreur systématique évitable","Une erreur aléatoire, inhérente à toutes les observations et résultant du hasard","La finesse de l'instrument de mesure","La validité externe de l'étude"],"r":1,"e":"La précision est associée à l'erreur de mesure : il y a toujours une divergence entre résultats observés et valeur vraie, inhérente à toutes les observations et résultant du hasard.","s":3},{"q":"Quelle différence essentielle sépare biais et erreur aléatoire ?","o":["Le biais peut être prévu et prévenu, l'erreur aléatoire ne peut jamais être éliminée","Le biais ne peut pas être corrigé, l'erreur aléatoire si","Les deux peuvent être éliminées totalement","Aucune : ce sont des synonymes"],"r":0,"e":"L'erreur systématique peut être prévue, prévenue et minimisée ; l'erreur aléatoire ne peut jamais être éliminée, seulement minimisée et estimée par l'analyse statistique.","s":3},{"q":"Comment peut-on minimiser l'erreur aléatoire ?","o":["Par l'aveuglement","Par la taille de l'échantillon, et son effet est estimé par l'analyse statistique","Par une meilleure randomisation","Par des critères d'inclusion plus stricts"],"r":1,"e":"L'erreur aléatoire peut être minimisée, par exemple par la taille de l'échantillon, et son effet doit être estimé par l'analyse statistique (valeur p).","s":3},{"q":"Que signifie l'acronyme RAMBOMAN ?","o":["Recrutement, Allocation, Maintien, Aveuglement, Objectif, Mesures, Analyse","Randomisation, Analyse, Méthode, Biais, Outcome, Manipulation, Anonymat","Revue, Article, Méthode, Base, Objectif, Mesure, Analyse","Résultats, Approche, Modèle, Bilan, Observation, Méta, Analyse"],"r":0,"e":"RAMBOMAN = Recrutement, Allocation, Maintien, Aveuglement/dissimulation, Objectif, Mesures, ANalyse.","s":3},{"q":"Quand utilise-t-on des études observationnelles ?","o":["Quand on veut absolument prouver une causalité","Quand il n'est pas possible, ou n'a pas de sens, de manipuler des variables","Quand le budget est illimité","Quand l'échantillon est très homogène"],"r":1,"e":"Les études observationnelles sont utilisées quand il n'est pas possible, ou n'a pas de sens, de manipuler des variables : on mesure des variables, il n'y a pas d'intervention.","s":3},{"q":"Quel est le principal inconvénient des études observationnelles ?","o":["Leur coût très élevé","On ne contrôle pas les conditions d'exposition et le potentiel de biais est plus grand","Elles sont toujours très lentes","Elles nécessitent une randomisation complexe"],"r":1,"e":"Les inconvénients sont l'absence de contrôle des conditions d'exposition et un plus grand potentiel de biais des résultats.","s":3},{"q":"Dans une étude de cohorte, que fait le chercheur ?","o":["Il évalue l'exposition avant l'outcome, partant de la cause pour identifier la conséquence","Il évalue l'outcome avant l'exposition","Il évalue les deux en même temps","Il manipule l'intervention"],"r":0,"e":"Dans les études de cohorte, on évalue l'influence d'une exposition sur le développement de la maladie : on part de la cause pour identifier la conséquence, l'exposition étant évaluée avant l'outcome.","s":3},{"q":"Dans une étude cas-témoins, que fait le chercheur ?","o":["Il suit un groupe exposé et un groupe non exposé","Il mesure rétrospectivement l'exposition : l'effet est déjà connu et il cherche la cause","Il randomise les participants","Il évalue simultanément exposition et outcome"],"r":1,"e":"Dans les études cas-témoins, on mesure rétrospectivement l'exposition : l'effet est déjà connu et on cherche à identifier la cause.","s":3},{"q":"Qu'est-ce qui caractérise une étude transversale ?","o":["Une évaluation à plusieurs moments","Une évaluation une seule fois, sans suivi, avec outcome et exposition évalués en même temps","Un suivi prospectif d'une cohorte","Une randomisation des participants"],"r":1,"e":"L'étude transversale (cross sectional) comporte une évaluation UNE seule fois, sans suivi ; l'outcome est évalué en même temps que l'exposition.","s":3},{"q":"Quel design convient aux questions de diagnostic et de fréquence ?","o":["Les études transversales","Les études cas-témoins","Les études de cohorte","Les essais cliniques"],"r":0,"e":"Les études transversales correspondent aux questions de diagnostic et de fréquence.","s":3},{"q":"Quel design convient aux questions d'intervention ?","o":["Les études transversales","Les études cas-témoins","Les essais cliniques","Les études de prévalence"],"r":2,"e":"Les essais cliniques correspondent aux questions d'intervention.","s":3},{"q":"Une étude où l'on identifie un groupe avec l'outcome et un groupe sans, puis où l'on remonte dans le temps, est :","o":["Une cohorte","Une étude cas-témoins","Une étude transversale","Un essai randomisé"],"r":1,"e":"C'est une étude cas-témoins : on identifie un groupe avec présence de l'outcome et un autre sans, puis on remonte dans le temps pour comprendre quel facteur de risque a pu influencer la maladie.","s":3},{"q":"Si le chercheur ne manipule pas l'exposition et enregistre l'outcome APRÈS l'exposition, l'étude est :","o":["Transversale","Une cohorte","Cas-témoins","Un ECR"],"r":1,"e":"Dans l'arbre décisionnel, si l'outcome est enregistré après l'exposition, il s'agit d'une cohorte.","s":3},{"q":"Une étude qui décrit la population relève de quelle approche ?","o":["Analytique et quantitative","Descriptive et qualitative","Expérimentale","Méthodologique"],"r":1,"e":"Si l'étude décrit la population, elle est descriptive (recherche qualitative) ; si elle quantifie la relation entre variables, elle est analytique (recherche quantitative).","s":3},{"q":"Quelle est la différence entre un ECR et un N-ECR ?","o":["Le N-ECR n'a pas de groupe contrôle","Dans l'ECR l'allocation est aléatoire ou randomisée, pas dans le N-ECR","Le N-ECR est observationnel","Le N-ECR n'a pas d'intervention"],"r":1,"e":"Dans une étude expérimentale, si l'allocation est aléatoire ou randomisée, c'est un ECR ; si elle ne l'est pas, c'est un N-ECR.","s":3},{"q":"Quel est l'objectif de la randomisation ?","o":["Réduire le coût de l'étude","Rendre les groupes comparables","Augmenter la taille de l'échantillon","Permettre l'aveuglement du statisticien"],"r":1,"e":"La randomisation attribue aléatoirement les participants à l'intervention qu'ils vont recevoir, avec pour objectif de rendre les groupes comparables.","s":3},{"q":"Qu'est-ce que l'allocation concealment ?","o":["L'anonymisation des données","La dissimulation de la séquence d'allocation aux chercheurs, par exemple avec des enveloppes scellées","Le fait de cacher les résultats jusqu'à la publication","L'aveuglement de l'évaluateur"],"r":1,"e":"La séquence d'allocation doit être dissimulée aux chercheurs (allocation concealment), en utilisant par exemple des enveloppes scellées.","s":3},{"q":"Qu'est-ce qu'un aveuglement en double insu ?","o":["Le participant seul est aveuglé","Le participant et le chercheur sont aveuglés","Le participant, le chercheur et l'évaluateur sont aveuglés","Le statisticien seul est aveuglé"],"r":1,"e":"L'aveuglement simple concerne le participant, le double le participant et le chercheur, le triple le participant, le chercheur et l'évaluateur.","s":3},{"q":"Qu'est-ce qu'une étude quasi-expérimentale ?","o":["Une étude sans manipulation de variables","Une manipulation de variables sans groupe de contrôle OU sans randomisation","Un essai randomisé de petite taille","Une revue systématique"],"r":1,"e":"Les études quasi-expérimentales comportent une manipulation de variables, mais sans groupe de contrôle ou sans randomisation : ce sont des études de moindre rigueur et qualité méthodologique.","s":3},{"q":"Quel est un inconvénient des études expérimentales ?","o":["Un plus grand potentiel de biais","Une généralisation limitée car les participants sont très sélectionnés","L'absence de contrôle de l'intervention","L'impossibilité d'établir une causalité"],"r":1,"e":"Les inconvénients sont la généralisation limitée (participants très sélectionnés), la difficulté de recrutement, les questions éthiques, les coûts plus élevés et la logistique complexe.","s":3},{"q":"Comment se comparent ECR et real world studies en validité interne ?","o":["ECR élevée, real world basse","ECR basse, real world élevée","Les deux élevées","Les deux basses"],"r":0,"e":"Les ECR ont une validité interne élevée et une validité externe basse ; les real world studies ont l'inverse.","s":3},{"q":"Comment définit-on l'efficacité ?","o":["Le résultat de l'interaction du traitement avec son environnement","Une propriété intrinsèque d'une conduite biomédicale","Le rapport bénéfice/coût d'un traitement","La satisfaction du patient"],"r":1,"e":"L'efficacité est une propriété intrinsèque d'une conduite biomédicale ; l'effectivité est le résultat de l'interaction du traitement avec l'environnement d'application.","s":3},{"q":"Quel est le meilleur niveau de preuve pour répondre à une question d'effectivité ?","o":["Les ECR","Les real world studies, c'est-à-dire les études observationnelles","Les études de cas","Les avis d'experts"],"r":1,"e":"Le meilleur niveau de preuve pour l'efficacité, ce sont les ECR ; pour l'effectivité, ce sont les real world studies (observationnelles).","s":3},{"q":"Quelle phrase résume le rapport entre efficacité et effectivité ?","o":["L'efficacité garantit l'effectivité","L'efficacité ne se traduit pas toujours en effectivité","L'effectivité précède toujours l'efficacité","Les deux notions sont équivalentes"],"r":1,"e":"Le cours conclut que l'efficacité ne se traduit pas toujours en effectivité.","s":3},{"q":"Les trois grandes catégories d'études distinguées par le cours sont :","o":["Primaires, secondaires et méthodologiques","Quantitatives, qualitatives et mixtes","Observationnelles, expérimentales et descriptives","Prospectives, rétrospectives et transversales"],"r":0,"e":"Les primaires regroupent expérimentales et observationnelles ; les secondaires les scoping reviews, revues systématiques, méta-analyses et guidelines ; les méthodologiques la construction et la validation d'instruments.","s":3},{"q":"La validité interne peut être affectée par :","o":["Des erreurs de sélection des participants","Des erreurs systématiques dans la mesure ou dans la relation entre variables","Une taille d'échantillon trop faible uniquement","Le choix du logiciel statistique"],"r":1,"e":"La validité externe, elle, peut être affectée par des erreurs de sélection des participants, qui compromettent la généralisation à la population.","s":3},{"q":"L'exemple « les résultats ne s'appliquent pas à notre patient de 17 ans, l'échantillon comptant des adultes de plus de 18 ans » illustre un problème :","o":["De validité interne","De validité externe","De précision","De biais de mesure"],"r":1,"e":"L'étude peut être parfaitement conduite et ses conclusions vraies pour son échantillon : c'est leur transposition à ce patient qui fait défaut.","s":3},{"q":"Un biais se distingue d'une erreur aléatoire parce qu'il :","o":["Résulte du hasard","Est une erreur systématique, qui peut être prévue et prévenue dans le design","Ne peut jamais être minimisé","N'affecte que la validité externe"],"r":1,"e":"L'erreur aléatoire ne peut jamais être éliminée : elle est inhérente à toute observation. Seule son ampleur peut être réduite et son effet estimé.","s":3},{"q":"Le confounding bias concerne :","o":["La sélection des participants","La mesure des variables","La relation entre variables","L'analyse statistique"],"r":2,"e":"Les trois types sont le selection bias, sur le recrutement, le measurement bias, sur le recueil des données, et le confounding bias, sur la relation entre variables.","s":3},{"q":"L'effet de l'erreur aléatoire est estimé par :","o":["La valeur p","Le calcul du biais","La randomisation","L'aveuglement"],"r":0,"e":"Elle se minimise notamment par l'augmentation de la taille de l'échantillon, mais aucune conception d'étude ne peut la supprimer.","s":3},{"q":"Le M final de l'acronyme RAMBOMAN correspond à :","o":["Maintien","Mesures","Manipulation","Méthode"],"r":1,"e":"L'acronyme complet : Recrutement, Allocation, Maintien, Blinding, Objectif, Mesures, ANalyse. Le maintien correspond au premier M.","s":3},{"q":"Les études observationnelles sont indiquées quand :","o":["On veut prouver une causalité","Il n'est pas possible, ou n'a pas de sens, de manipuler des variables","On dispose de beaucoup de moyens","L'échantillon est très grand"],"r":1,"e":"Elles offrent moins de limitations éthiques et pratiques, sont moins coûteuses et plus rapides, mais exposent à un plus grand potentiel de biais.","s":3},{"q":"Dans une étude de cohorte, l'exposition est évaluée :","o":["Après l'outcome","Avant l'outcome : on part de la cause pour identifier la conséquence","En même temps que l'outcome","Elle n'est pas évaluée"],"r":1,"e":"L'étude cas-témoins procède en sens inverse : l'effet est déjà connu et l'on recherche rétrospectivement la cause.","s":3},{"q":"Une étude transversale se caractérise par le fait que :","o":["L'exposition précède l'outcome","L'outcome précède l'exposition","Outcome et exposition sont évalués en même temps, une seule fois","Aucune variable n'est mesurée"],"r":2,"e":"Cette simultanéité interdit d'établir une chronologie, donc de conclure à une causalité — mais convient aux questions de diagnostic et de fréquence.","s":3},{"q":"Selon la correspondance question-design, les questions d'étiologie et de pronostic appellent :","o":["Une étude transversale","Une étude cas-témoins ou de cohorte","Un essai clinique","Une revue systématique"],"r":1,"e":"Les questions de diagnostic et de fréquence appellent une étude transversale, les questions d'intervention un essai clinique.","s":3},{"q":"Un essai contrôlé randomisé associe :","o":["Manipulation et randomisation, sans groupe contrôle","Manipulation, groupe de contrôle et randomisation","Groupe de contrôle et randomisation, sans manipulation","Observation et suivi longitudinal"],"r":1,"e":"Une étude quasi-expérimentale comporte la manipulation mais lui manque soit le groupe de contrôle, soit la randomisation — d'où une moindre rigueur.","s":3},{"q":"L'aveuglement triple concerne :","o":["Le participant, le chercheur et l'évaluateur","Le participant et le chercheur","Le chercheur, l'évaluateur et le statisticien","Le participant seul"],"r":0,"e":"Le simple insu ne concerne que le participant, le double y ajoute le chercheur ; on peut aller au-delà en aveuglant aussi le statisticien.","s":3},{"q":"L'allocation concealment consiste à :","o":["Cacher le traitement au patient","Dissimuler la séquence d'allocation, par exemple au moyen d'enveloppes scellées","Masquer les résultats à l'évaluateur","Randomiser après inclusion"],"r":1,"e":"Si l'investigateur peut deviner le groupe suivant, il risque d'orienter les inclusions — ce qui détruit l'équilibre que la randomisation devait produire.","s":3},{"q":"Les essais contrôlés randomisés se caractérisent par :","o":["Une validité interne élevée et une validité externe basse","Une validité interne basse et une validité externe élevée","Les deux validités élevées","Les deux validités basses"],"r":0,"e":"Les real world studies présentent le profil inverse : conditions réelles donc bonne généralisation, mais contrôle faible des facteurs de confusion.","s":3},{"q":"L'efficacité, au sens du cours, se définit comme :","o":["Le résultat de l'interaction du traitement avec son environnement d'application","Une propriété intrinsèque d'une conduite biomédicale","Le rapport coût-bénéfice","La satisfaction du patient"],"r":1,"e":"Son meilleur niveau de preuve est l'essai contrôlé randomisé. L'effectivité, elle, s'évalue au mieux par les real world studies.","s":3},{"q":"Le cours souligne à propos du couple efficacité / effectivité que :","o":["Les deux se confondent","L'efficacité ne se traduit pas toujours en effectivité","L'effectivité précède toujours l'efficacité","Seule l'efficacité compte en clinique"],"r":1,"e":"Un traitement peut fonctionner dans les conditions idéales d'un essai et décevoir en pratique courante — du fait de l'observance, des comorbidités ou de l'organisation des soins.","s":3},{"q":"Les études observationnelles présentent comme avantage :","o":["La participation des individus en contexte naturel","Un contrôle strict des conditions d'exposition","Une absence totale de biais","Une preuve de causalité"],"r":0,"e":"Leur inconvénient principal est précisément l'absence de contrôle des conditions d'exposition, d'où un potentiel de biais accru.","s":3},{"q":"La précision d'une étude est associée à :","o":["L'erreur systématique","L'erreur de mesure inhérente à toute observation, due au hasard","La sélection des participants","La validité externe"],"r":1,"e":"Il existe toujours une divergence entre résultat observé et valeur vraie. Cette imprécision affecte l'estimation, non la direction du résultat.","s":3},{"q":"Une étude où le chercheur identifie un groupe avec l'outcome et un groupe sans, puis recherche l'exposition passée, est :","o":["Une cohorte","Une étude cas-témoins","Une étude transversale","Un essai randomisé"],"r":1,"e":"C'est le design de choix pour les événements rares : partir de l'effet permet de constituer un groupe suffisant, ce qu'une cohorte exigerait d'immense.","s":3},{"q":"Qu'est-ce qui caractérise une revue de la littérature simple ?","o":["Elle est réalisée sans critères d'éligibilité","Elle évalue systématiquement le risque de biais","Elle combine statistiquement les résultats","Elle nécessite un enregistrement PROSPERO"],"r":0,"e":"La revue de la littérature se fait sans critères d'éligibilité, contrairement à la revue systématique.","s":4},{"q":"Qu'est-ce qu'une umbrella review ?","o":["Une revue sur un sujet très large","Une revue des revues systématiques","Une revue rapide multicentrique","Une méta-analyse de données individuelles"],"r":1,"e":"L'umbrella review est une revue des revues systématiques.","s":4},{"q":"Quelle caractéristique définit la rapid review ?","o":["Elle n'utilise qu'un seul relecteur et exclut certaines étapes de la revue systématique","Elle suit exactement le protocole PRISMA","Elle inclut toujours une méta-analyse","Elle exige au moins trois évaluateurs"],"r":0,"e":"La rapid review exclut certaines étapes d'une RS, synthétise de façon descriptive, n'utilise qu'un seul relecteur et il n'existe pas de critères standard pour sa réalisation.","s":4},{"q":"Quel est l'objet principal d'une scoping review ?","o":["Mesurer l'efficacité d'une intervention","Cartographier la littérature dans un domaine d'intérêt déterminé","Combiner statistiquement les essais","Produire des recommandations cliniques"],"r":1,"e":"La scoping review est une cartographie de la littérature dans un domaine d'intérêt déterminé ; elle n'est pas focalisée sur les effets et caractérise une intervention de santé.","s":4},{"q":"Quelle différence majeure sépare scoping review et revue systématique ?","o":["La scoping review n'évalue pas la qualité des études, la revue systématique évalue la qualité méthodologique","La scoping review est plus complète","La revue systématique n'a pas de critères d'éligibilité","La scoping review inclut toujours une méta-analyse"],"r":0,"e":"La scoping review n'évalue pas la qualité des études ; la revue systématique évalue la qualité méthodologique des articles et est plus complète.","s":4},{"q":"Quelle stratégie de question correspond aux scoping reviews ?","o":["PICOT","PECOT","PCC (Population / Concept / Contexte)","POT"],"r":2,"e":"PCC — Population, Concept, Contexte — s'applique aux scoping reviews.","s":4},{"q":"Lequel de ces objectifs n'appartient PAS à la scoping review ?","o":["Évaluer l'étendue et la nature des études scientifiques","Identifier la faisabilité de réaliser une revue systématique","Identifier les lacunes de la littérature","Établir la supériorité statistique d'une intervention"],"r":3,"e":"La scoping review n'est pas focalisée sur les effets : elle cartographie, clarifie des concepts, évalue la faisabilité d'une RS et identifie les lacunes.","s":4},{"q":"Qui est à l'origine de la revue systématique en 1979 ?","o":["Archie Cochrane","David Sackett","Iain Chalmers","Gordon Guyatt"],"r":0,"e":"Archie Cochrane, en 1979, critiquait l'absence d'un résumé critique adapté périodiquement de tous les essais cliniques randomisés pertinents.","s":4},{"q":"Comment le cours définit-il la revue systématique ?","o":["Une synthèse narrative des publications d'un domaine","Une revue qui recueille l'évidence selon des critères d'éligibilité définis pour répondre à une question clinique spécifique, avec des méthodes explicites et reproductibles","Un avis d'experts structuré","Une compilation de guidelines"],"r":1,"e":"La RS recueille l'évidence scientifique selon des critères d'éligibilité définis pour répondre à une question clinique spécifique, en utilisant des méthodes explicites, reproductibles et systématisées afin de minimiser le risque de biais.","s":4},{"q":"Combien de phases comporte la réalisation d'une revue systématique selon le cours ?","o":["5","7","9","12"],"r":2,"e":"Le cours détaille 9 phases, de la définition de la question à l'interprétation des résultats et aux recommandations.","s":4},{"q":"Combien de temps peut prendre le processus complet d'une revue systématique ?","o":["Quelques jours","Environ un mois","Plus d'un an","Au moins cinq ans"],"r":2,"e":"Le cours précise que compléter tout le processus d'une RS peut prendre plus d'un an.","s":4},{"q":"Sur quelle plateforme enregistre-t-on le titre d'une revue systématique ?","o":["PROSPERO","PRISMA","AMSTAR","Rayyan"],"r":0,"e":"L'enregistrement du titre des revues systématiques se fait sur PROSPERO.","s":4},{"q":"Quelle stratégie de question est utilisée en phase 1 d'une revue systématique ?","o":["PCC","PICOS","POT","PICo"],"r":1,"e":"La phase 1 de la revue systématique définit la question de recherche avec le PICOS.","s":4},{"q":"Que produisent des critères d'éligibilité plus stricts ?","o":["Ils évitent l'hétérogénéité des études et diminuent le biais","Ils augmentent l'hétérogénéité","Ils réduisent la validité interne","Ils augmentent le nombre d'études incluses"],"r":0,"e":"Des critères plus stricts évitent l'hétérogénéité des études et diminuent le biais ; des critères plus souples incluent des études hétérogènes et explorent l'évidence disponible.","s":4},{"q":"Combien de bases de données au minimum le cours recommande-t-il ?","o":["Une seule","Au moins 2","Au moins 3","Au moins 5"],"r":2,"e":"La stratégie de recherche doit couvrir au moins 3 bases de données, avec 2 ou 3 évaluateurs.","s":4},{"q":"Comment se fait la sélection des études en phase 4 ?","o":["Par un seul chercheur","Par deux chercheurs indépendants aveugles, avec un 3e pour consensus si nécessaire","Automatiquement par logiciel","Par le comité d'éthique"],"r":1,"e":"La sélection repose sur l'évaluation des titres et abstracts par deux chercheurs indépendants aveugles, avec un 3e chercheur pour consensus si nécessaire et un niveau de concordance entre évaluateurs.","s":4},{"q":"Quel outil facilite la sélection des études d'une revue systématique ?","o":["Rayyan","AMSTAR","GRADE","PROSPERO"],"r":0,"e":"Rayyan est cité comme outil d'aide pour la sélection des études, avec le diagramme de flux.","s":4},{"q":"Combien d'évaluateurs au minimum pour l'évaluation de la qualité des études (phase 7) ?","o":["Un seul","Au moins 2, avec calcul du niveau de concordance (k)","Au moins 4","Le nombre est libre"],"r":1,"e":"L'analyse indépendante se fait par au moins 2 évaluateurs, avec calcul du niveau de concordance (k), suivie d'une réunion de consensus.","s":4},{"q":"Que signifie GRADE ?","o":["Grading of Recommendations Assessment, Development and Evaluation","General Research Assessment of Data Evidence","Guideline Rating and Development Evaluation","Global Risk Assessment of Diagnostic Evidence"],"r":0,"e":"GRADE signifie Grading of Recommendations Assessment, Development and Evaluation : c'est l'évaluation de la certitude de l'évidence.","s":4},{"q":"Lequel de ces domaines N'EST PAS un domaine de GRADE ?","o":["Incohérence","Évidence indirecte","Biais de publication","Taille du budget de l'étude"],"r":3,"e":"Les cinq domaines de GRADE sont : limites de l'étude/risque de biais, incohérence, évidence indirecte, imprécision et biais de publication.","s":4},{"q":"En quoi doit être divisée la conclusion d'une revue systématique ?","o":["En points forts et points faibles","En implications pour la pratique clinique et implications pour la recherche","En résultats positifs et négatifs","En sections méthodologique et statistique"],"r":1,"e":"La conclusion d'une revue systématique devra être divisée en implications pour la pratique clinique et implications pour la recherche.","s":4},{"q":"Quelle checklist sert à rapporter une revue systématique ?","o":["CONSORT","PRISMA","STROBE","CARE"],"r":1,"e":"PRISMA est la guideline et checklist de référence pour rapporter les revues systématiques, avec son diagramme de flux.","s":4},{"q":"À quoi sert AMSTAR ?","o":["À rapporter un essai clinique","À évaluer la qualité et le risque de biais des revues systématiques","À calculer la taille d'échantillon","À enregistrer un protocole"],"r":1,"e":"AMSTAR (A MeaSurement Tool to Assess systematic Reviews) sert, avec la CASP Checklist, à évaluer la qualité et le risque de biais des revues systématiques.","s":4},{"q":"Que signifie le H du FAITH check ?","o":["Hypothèses","Les résultats sont-ils hétérogènes ?","Homogénéité de la population","Haute qualité des études"],"r":1,"e":"Le H du FAITH check pose la question : les résultats sont-ils hétérogènes ?","s":4},{"q":"Quel outil le FAITH check recommande-t-il d'utiliser pour évaluer les études individuellement ?","o":["Le RAMBOMAN","Le GRADE","Le PRISMA","Le CONSORT"],"r":0,"e":"Le A du FAITH check — ont-ils évalué les études individuellement ? — renvoie à l'utilisation du RAMBOMAN.","s":4},{"q":"Combien d'études primaires minimum une méta-analyse intègre-t-elle ?","o":["Deux","Trois ou plus","Cinq ou plus","Dix ou plus"],"r":1,"e":"La méta-analyse est la méthode statistique incluse dans une RS qui intègre les résultats de trois études primaires ou plus.","s":4},{"q":"Quelle est la différence d'analyse entre revue systématique et méta-analyse ?","o":["La RS fait une analyse qualitative étude par étude, la méta-analyse une analyse quantitative des études ensemble","La RS est quantitative, la méta-analyse qualitative","Les deux sont purement qualitatives","Les deux sont purement quantitatives"],"r":0,"e":"La revue systématique fait une analyse qualitative de chaque étude individuellement ; la méta-analyse fait une analyse quantitative, analysant les études ensemble et sommant l'effet.","s":4},{"q":"Dans quel cas NE faut-il PAS réaliser de méta-analyse ?","o":["Quand il existe des variations significatives dans les questions cliniques des études, ou si les études ont des biais importants","Quand il y a plus de dix études","Quand les études sont très semblables","Quand l'effet est important"],"r":0,"e":"Il ne faut pas faire de méta-analyse en cas de variations significatives des questions cliniques, quand la diversité des études prive les résultats de signification réelle, ou si les études ont des biais importants.","s":4},{"q":"Que montre un forest plot ?","o":["Le diagramme de flux de la sélection","Une suggestion visuelle de l'hétérogénéité et l'effet commun estimé","La certitude de l'évidence selon GRADE","La chronologie des publications"],"r":1,"e":"Le forest plot résume les informations des études individuellement, donne une suggestion visuelle de l'hétérogénéité et montre l'effet commun estimé, indiquant si l'intervention est bénéfique ou non.","s":4},{"q":"Comment le cours présente-t-il les guidelines ?","o":["Comme des ordres aveugles à respecter","Comme des règles de bonne pratique clinique, qui peuvent être discutées, diffusées et doivent être respectées","Comme des documents purement indicatifs sans valeur","Comme des consensus d'experts sans base scientifique"],"r":1,"e":"Les guidelines ne sont pas des ordres aveugles : ce sont des règles de bonne pratique clinique, qui peuvent être discutées, diffusées et doivent être respectées.","s":4},{"q":"Une umbrella review est :","o":["Une revue de la littérature sans critères d'éligibilité","Une revue des revues systématiques","Une revue rapide","Une cartographie de la littérature"],"r":1,"e":"Les cinq types recensés : revue de la littérature, revue rapide, scoping review, revue systématique avec ou sans méta-analyse, et umbrella review.","s":4},{"q":"La revue rapide se caractérise notamment par :","o":["L'usage d'un seul relecteur et l'absence de critères standard de réalisation","Une évaluation exhaustive du risque de biais","Trois relecteurs indépendants","Un enregistrement obligatoire sur PROSPERO"],"r":0,"e":"Elle exclut certaines étapes d'une revue systématique et synthétise les résultats de façon descriptive. Le cours cite la pandémie comme contexte typique d'usage.","s":4},{"q":"La scoping review n'évalue pas :","o":["L'étendue de la littérature","La qualité méthodologique des études incluses","La nature des études","Les lacunes de la littérature"],"r":1,"e":"Elle cartographie sans juger : son objet est de caractériser une intervention et de délimiter un champ, non de conclure sur l'efficacité.","s":4},{"q":"La stratégie de question propre à la scoping review est :","o":["PICO","PCC","SPIDER","PEO"],"r":1,"e":"Population, Concept, Context. Les autres déclinaisons de PICO servent selon le type d'étude : qualitative, non expérimentale, de prévalence.","s":4},{"q":"Parmi les objectifs de la scoping review, le cours cite :","o":["Identifier la faisabilité ou la pertinence de réaliser une revue systématique","Calculer un effet commun","Évaluer le risque de biais","Formuler des recommandations de grade A"],"r":0,"e":"C'est un exercice préliminaire qui affine la question de revue. Elle sert aussi à clarifier des concepts et à repérer les lacunes de la littérature.","s":4},{"q":"La revue systématique a pour caractéristique méthodologique essentielle :","o":["D'utiliser des méthodes explicites, reproductibles et systématisées afin de minimiser le risque de biais","De rassembler toute la littérature disponible sans tri","De se limiter aux essais randomisés","D'être réalisée par un seul auteur"],"r":0,"e":"Elle recueille l'évidence selon des critères d'éligibilité définis pour répondre à une question clinique spécifique, et évalue la qualité méthodologique des articles inclus.","s":4},{"q":"L'origine de la revue systématique est attribuée à :","o":["Sackett, 2000","Archie Cochrane, 1979","Beaton, 2000","Rothstein, 1995"],"r":1,"e":"La collaboration Cochrane, qui porte son nom, constitue aujourd'hui la référence méthodologique pour la réalisation des revues systématiques.","s":4},{"q":"La revue systématique comporte, selon le cours :","o":["5 phases","7 phases","9 phases","12 phases"],"r":2,"e":"De la question aux recommandations, en passant par critères d'éligibilité, stratégie de recherche, sélection, filtrage, extraction, évaluation de la qualité et analyse. Le processus peut dépasser un an.","s":4},{"q":"L'enregistrement du titre d'une revue systématique se fait sur :","o":["PRISMA","PROSPERO","AMSTAR","GRADE"],"r":1,"e":"Les jalons de publication se suivent dans cet ordre : enregistrer le titre, publier le protocole, publier la revue, publier la mise à jour.","s":4},{"q":"La stratégie de recherche d'une revue systématique exige au minimum :","o":["Une base de données","Deux bases de données","Trois bases de données","Cinq bases de données"],"r":2,"e":"S'y ajoutent les mots-clés et leurs combinaisons, le choix entre texte intégral et résumés, et le recours à deux ou trois évaluateurs.","s":4},{"q":"La sélection des articles dans une revue systématique se fait :","o":["Par un seul chercheur","Par deux chercheurs indépendants aveugles, avec un troisième pour consensus","Par vote majoritaire de l'équipe","Automatiquement par logiciel"],"r":1,"e":"Le niveau de concordance entre évaluateurs, mesuré par le coefficient kappa, documente la fiabilité de cette étape.","s":4},{"q":"GRADE évalue la certitude de l'évidence selon :","o":["Trois domaines","Quatre domaines","Cinq domaines","Sept domaines"],"r":2,"e":"Limites de l'étude ou risque de biais, incohérence, évidence indirecte, imprécision et biais de publication.","s":4},{"q":"L'outil AMSTAR sert à :","o":["Rapporter une revue systématique","Évaluer la qualité d'une revue systématique","Sélectionner les articles","Analyser les données"],"r":1,"e":"CASP remplit une fonction voisine. PRISMA est la guideline de rapport, Rayyan un outil de sélection, INSPECT-SR un détecteur d'essais problématiques.","s":4},{"q":"Une méta-analyse intègre les résultats :","o":["De deux études au minimum","De trois études primaires ou plus","De dix études au minimum","D'une seule étude de grande taille"],"r":1,"e":"C'est une méthode statistique incluse dans une revue systématique lorsque c'est pertinent, qui ajoute une évaluation quantitative à l'analyse qualitative.","s":4},{"q":"Le forest plot d'une méta-analyse :","o":["Classe les études par date","Résume les études et montre l'effet commun estimé","Évalue le risque de biais","Présente la stratégie de recherche"],"r":1,"e":"Chaque étude y apparaît avec son effet et son intervalle de confiance ; le losange final synthétise l'estimation combinée.","s":4},{"q":"Les guidelines sont décrites dans le cours comme :","o":["Des ordres à appliquer aveuglément","Des règles de bonne pratique, qui peuvent être discutées et doivent être respectées","De simples suggestions sans portée","Des textes réglementaires"],"r":1,"e":"Cette formulation équilibrée écarte deux erreurs symétriques : l'application mécanique et le rejet au nom de la liberté clinique.","s":4},{"q":"La revue de la littérature se distingue des autres types de revue parce qu'elle :","o":["Applique des critères d'éligibilité stricts","Ne définit pas de critères d'éligibilité","Évalue le risque de biais","Inclut une méta-analyse"],"r":1,"e":"C'est cette absence de critères explicites qui la rend non reproductible : deux auteurs sur le même sujet n'aboutiraient pas au même corpus.","s":4},{"q":"Le domaine GRADE dit « évidence indirecte » concerne :","o":["Des études dont la population, l'intervention ou l'outcome diffèrent de la question posée","Des résultats contradictoires entre études","Des intervalles de confiance larges","Des études non publiées"],"r":0,"e":"L'incohérence désigne les résultats contradictoires, l'imprécision les intervalles larges, le biais de publication la non-publication des résultats négatifs.","s":4},{"q":"Le coefficient kappa, utilisé lors de la sélection des articles, mesure :","o":["La taille d'effet","Le niveau de concordance entre évaluateurs","La qualité méthodologique","L'hétérogénéité"],"r":1,"e":"Une concordance faible signale des critères d'éligibilité mal définis, qu'il faut clarifier avant de poursuivre la sélection.","s":4},{"q":"L'outil Rayyan sert à :","o":["Évaluer le risque de biais","Faciliter la sélection des articles","Rédiger le rapport","Réaliser la méta-analyse"],"r":1,"e":"Il permet à plusieurs relecteurs de trier les références en aveugle, puis de confronter leurs décisions — ce que la méthode exige explicitement.","s":4},{"q":"Comment le cours définit-il la mesure ?","o":["La quantification de caractéristiques déterminées","L'interprétation d'informations cliniques","L'observation du patient","La comparaison entre deux groupes"],"r":0,"e":"La mesure est la quantification de caractéristiques déterminées ; l'évaluation est le processus de sélection, recueil, analyse et interprétation d'information clinique.","s":5},{"q":"Qu'englobe l'évaluation selon le cours ?","o":["Uniquement des données objectives","Un processus de sélection, recueil, analyse et interprétation d'information clinique subjective ET objective","Uniquement le ressenti du patient","Uniquement les mesures instrumentales"],"r":1,"e":"L'évaluation est le processus de sélection, recueil, analyse et interprétation d'information clinique, subjective et objective.","s":5},{"q":"Quel exemple correspond à un résultat clinique ?","o":["La qualité de vie","L'amplitude de mouvement, le tonus, la force musculaire","Le nombre de séances","Le niveau de satisfaction"],"r":1,"e":"Les résultats cliniques donnent la perspective des professionnels de santé : ROM, tonus, force musculaire.","s":5},{"q":"Quel exemple correspond à un résultat économique ?","o":["L'intensité de la douleur","La productivité, le nombre de séances et les coûts","Le tonus musculaire","La qualité de vie"],"r":1,"e":"Les résultats économiques donnent la perspective du payeur et de la société : productivité, nombre de séances, coûts.","s":5},{"q":"Qu'est-ce qu'un Core Outcome Set ?","o":["La liste complète de tous les résultats mesurables","Un ensemble minimal de domaines de résultats fondamentaux pour la prise de décisions cliniques, qui doivent être mesurés dans les études","Un questionnaire validé","Un modèle statistique"],"r":1,"e":"Un COS est un ensemble minimal de domaines de résultats considérés fondamentaux pour la prise de décisions cliniques et qui doivent être mesurés dans les études de recherche.","s":5},{"q":"Quelle initiative est citée comme ressource pour les Core Outcome Sets ?","o":["COMET","COSMIN","PROSPERO","PRISMA"],"r":0,"e":"Le cours renvoie à comet-initiative.org et ichom.org pour les Core Outcome Sets ; COSMIN concerne les propriétés psychométriques.","s":5},{"q":"Quelle est la différence entre construit et instrument ?","o":["Le construit est ce que l'on prétend mesurer, l'instrument est comment on le mesure","Le construit est l'outil, l'instrument est la théorie","Ils sont synonymes","Le construit est toujours quantitatif"],"r":0,"e":"Le concept/construit ou domaine est ce que l'on prétend mesurer ; les méthodes et instruments définissent comment le construit est mesuré.","s":5},{"q":"Qu'évaluent les PREM ?","o":["La satisfaction ou la qualité de l'expérience","Les résultats de l'intervention sur la santé","L'amplitude de mouvement","Les coûts de la prise en charge"],"r":0,"e":"Les PREM, Patient-Reported Experience Measures, évaluent la satisfaction et la qualité de l'expérience ; les PROM évaluent la qualité de l'intervention et des résultats sur la santé.","s":5},{"q":"Lequel de ces instruments est un PROM cité dans le cours ?","o":["Le Hospital Consumer Assessment of Health Care Providers and Systems","Le SF-36 et l'EuroQol EQ-5D","L'oxymètre","Le grade de force musculaire"],"r":1,"e":"Le SF-36 et l'EuroQol EQ-5D sont donnés comme exemples de PROM ; le Hospital Consumer Assessment est un exemple de PREM.","s":5},{"q":"À quelle catégorie appartient le SF-36 parmi les types d'instruments ?","o":["Générique (qualité de vie)","Spécifique d'une région du corps","Spécifique de signes et symptômes","Spécifique d'une population"],"r":0,"e":"Le SF-36 est cité comme instrument générique de qualité de vie.","s":5},{"q":"À quelle catégorie appartient le McGill Pain Questionnaire ?","o":["Générique","Spécifique de signes et symptômes","Spécifique de population","Spécifique de région du corps"],"r":1,"e":"Le McGill Pain Questionnaire est un instrument spécifique de signes et symptômes.","s":5},{"q":"À quelle catégorie appartient le Cincinnati Knee Rating System ?","o":["Spécifique d'une région du corps","Générique","Spécifique d'une population","Spécifique d'un domaine"],"r":0,"e":"Le Cincinnati Knee Rating System est spécifique d'une région du corps.","s":5},{"q":"Quelles sont les trois qualités fondamentales d'un instrument de mesure ?","o":["Rapidité, coût et simplicité","Validité, fiabilité et sensibilité au changement","Généralisabilité, précision et reproductibilité","Traduction, adaptation et publication"],"r":1,"e":"Un instrument doit être valide (il mesure ce qu'il est censé mesurer), fiable (information cohérente) et sensible au changement (il détecte des changements au fil du temps).","s":5},{"q":"Que signifie COSMIN ?","o":["COnsensus based Standards for the selection of health Measurement INstruments","COre Set of Measurement INstruments","COmparative Standard of Medical INstruments","COnsortium for Standardized Medical INdicators"],"r":0,"e":"COSMIN signifie COnsensus based Standards for the selection of health Measurement INstruments.","s":5},{"q":"Comment définit-on la validité d'un instrument ?","o":["La cohérence de l'information produite","La propriété de mesurer ce que l'on prétend qu'il mesure","La capacité à détecter des changements","La facilité de calcul du score"],"r":1,"e":"La validité est la propriété de mesurer ce que l'on prétend qu'il mesure : la qualité d'un instrument quand il mesure bien la réalité pour laquelle il a été construit.","s":5},{"q":"Que vérifie la validité de contenu ?","o":["Si les items reflètent de façon adéquate le construit à mesurer et incluent les aspects les plus pertinents","Si l'instrument confirme une théorie","Si les scores sont reproductibles dans le temps","Si l'instrument détecte le changement"],"r":0,"e":"La validité de contenu cherche à répondre si le contenu et les items d'un instrument reflètent de façon adéquate le construit à mesurer, incluant les aspects les plus adéquats, importants et pertinents.","s":5},{"q":"Que concerne la validité de construit ?","o":["La traduction de l'instrument","La validation d'une théorie, avec confirmation d'hypothèses et vérification des relations entre scores","La comparaison entre deux observateurs","Le temps d'application"],"r":1,"e":"La validité de construit se réfère à la validation d'une théorie : il y a confirmation d'hypothèses et on vérifie si les scores de l'instrument sont reliés les uns aux autres.","s":5},{"q":"Comment définit-on la fiabilité ?","o":["La capacité à mesurer ce qui est censé être mesuré","La précision ou la cohérence de l'information, c'est-à-dire la même réponse indépendamment de la façon et du moment d'application","La capacité à détecter un changement minimal important","La pertinence culturelle"],"r":1,"e":"La fiabilité concerne la précision ou la cohérence de l'information : elle évalue dans quelle mesure une procédure produit la même réponse indépendamment de la façon et du moment où elle est appliquée.","s":5},{"q":"Quel indicateur mesure la cohérence interne ?","o":["Le coefficient kappa","L'alpha de Cronbach","Le coefficient de corrélation intraclasse","La valeur p"],"r":1,"e":"L'alpha de Cronbach est l'indicateur le plus utilisé pour la cohérence interne ; ses valeurs varient entre 0 et 0,95.","s":5},{"q":"Quel seuil d'alpha de Cronbach indique une bonne consistance interne ?","o":["Égal ou supérieur à 0,3","Égal ou supérieur à 0,5","Égal ou supérieur à 0,7","Égal ou supérieur à 0,95"],"r":2,"e":"Le cours retient une consistance interne égale ou supérieure à 0,7 ; les valeurs de l'alpha varient entre 0 et 0,95.","s":5},{"q":"Comment évalue-t-on la fiabilité test-retest ?","o":["En appliquant la mesure à la même population à différents moments et en comparant les scores","En comparant deux évaluateurs différents","En corrélant les items entre eux","En mesurant l'erreur de score"],"r":0,"e":"La fiabilité test-retest, ou stabilité intertemporelle, s'évalue par l'application de la mesure à la même population à différents moments et par comparaison des scores obtenus.","s":5},{"q":"Comment choisir l'intervalle entre test et retest ?","o":["Le plus court possible","Suffisant pour que les participants ne se souviennent pas des réponses, mais pas assez long pour qu'un changement réel survienne","Au moins un an","L'intervalle n'a pas d'importance"],"r":1,"e":"L'intervalle doit être suffisant pour que les participants ne répliquent pas les réponses originales, mais pas si long qu'il permette la survenue d'un changement réel.","s":5},{"q":"Qu'est-ce que l'erreur de mesure ?","o":["Une faute de calcul du score","Une erreur de score de l'instrument qui ne peut pas être attribuée à des changements du construit mesuré","Un biais de sélection","Une différence entre deux populations"],"r":1,"e":"L'erreur de mesure est l'erreur de score de l'instrument qui ne peut pas être attribuée à des changements du construit mesuré.","s":5},{"q":"Comment définit-on la réactivité ?","o":["La rapidité d'application de l'instrument","La capacité à détecter des changements au fil du temps définis comme minimaux et considérés importants","La cohérence entre les items","La pertinence des items"],"r":1,"e":"La réactivité est la capacité à détecter des changements au fil du temps définis comme minimaux et considérés importants ; elle comprend pouvoir de réponse, interprétabilité, sensibilité et spécificité.","s":5},{"q":"Qu'est-ce que l'interprétabilité d'un instrument ?","o":["Le degré selon lequel on peut attribuer une signification qualitative aux valeurs quantitatives obtenues","La facilité de traduction","La rapidité de passation","La corrélation entre items"],"r":0,"e":"L'interprétabilité, ou pouvoir interprétatif, est le degré selon lequel on peut attribuer une signification qualitative facilement compréhensible aux valeurs quantitatives obtenues par l'instrument.","s":5},{"q":"Qu'est-ce que la sensibilité d'un test ?","o":["La capacité à identifier correctement les individus qui présentent la maladie ou le résultat","La capacité à identifier correctement les individus sains","La reproductibilité du test","La rapidité du test"],"r":0,"e":"La sensibilité est la capacité du test à identifier correctement les individus qui présentent une maladie déterminée ou un autre résultat (résultat +).","s":5},{"q":"Quel est l'ordre d'importance des critères psychométriques selon le cours ?","o":["Validité de contenu, puis consistance interne, puis les autres validités, fiabilités et la réactivité","Réactivité, puis fiabilité, puis validité","Consistance interne, puis réactivité, puis validité","Tous ont la même importance"],"r":0,"e":"L'ordre d'importance est : 1. validité — validité de contenu ; 2. fiabilité — consistance interne ; 3. autres validités, fiabilités et la réactivité.","s":5},{"q":"Quelle référence encadre l'adaptation transculturelle d'instruments ?","o":["Beaton et al., 2000","Domholdt, 2000","Rothstein, 1995","Cochrane, 1979"],"r":0,"e":"Le processus d'adaptation transculturelle suit Beaton et al. (2000), qui garantit l'équivalence conceptuelle et sémantique avec l'original.","s":5},{"q":"Quelle exigence pèse sur les rétrotraducteurs (étape 3) ?","o":["Être des professionnels de santé expérimentés","Être « aveugles » et de préférence appartenir à un autre domaine de connaissance que la santé","Être les mêmes que les traducteurs de l'étape 1","Être au moins quatre"],"r":1,"e":"Les rétrotraducteurs doivent être de même langue maternelle que celle de l'instrument original, être « aveugles » et de préférence appartenir à un autre domaine de connaissance que celui de la santé.","s":5},{"q":"Combien de participants le pré-test doit-il idéalement compter ?","o":["10 à 15","30 à 40","100 à 150","Au moins 300"],"r":1,"e":"Le pré-test devra idéalement compter 30 à 40 participants volontaires afin d'établir la validation de contenu de l'échelle.","s":5},{"q":"Parmi les résultats cliniques, le cours cite :","o":["L'amplitude articulaire, le tonus et la force musculaire","La qualité de vie","Le nombre de séances","La satisfaction"],"r":0,"e":"Les résultats humanistiques relèvent de la perspective des patients et des proches ; les résultats économiques de celle du payeur et de la société.","s":5},{"q":"Un construit, en méthodologie de la mesure, désigne :","o":["L'instrument utilisé","Ce que l'on prétend mesurer","Le résultat obtenu","La population cible"],"r":1,"e":"L'instrument est le moyen par lequel le construit est mesuré. Confondre les deux revient à prendre le thermomètre pour la température.","s":5},{"q":"Les PREM évaluent :","o":["Les résultats sur la santé","La satisfaction et la qualité de l'expérience vécue","Les coûts","Les amplitudes articulaires"],"r":1,"e":"Les PROM évaluent la satisfaction et la qualité de l'intervention ainsi que ses résultats sur la santé ; le SF-36 et l'EuroQol EQ-5D en sont des exemples.","s":5},{"q":"Le McGill Pain Questionnaire est cité comme instrument :","o":["Générique","Spécifique d'une condition","Spécifique de signes et symptômes","Spécifique d'une région du corps"],"r":2,"e":"Le SF-36 est l'exemple d'instrument générique. Les six types recensés couvrent aussi les instruments spécifiques d'une population et d'un domaine.","s":5},{"q":"Les trois critères psychométriques fondamentaux sont :","o":["Validité, fiabilité et réactivité","Sensibilité, spécificité et précision","Fidélité, exactitude et reproductibilité","Pertinence, faisabilité et coût"],"r":0,"e":"COSMIN en est la référence méthodologique. Par ordre d'importance : validité de contenu, consistance interne, puis les autres validités, fiabilités et la réactivité.","s":5},{"q":"La réactivité d'un instrument désigne sa capacité à :","o":["Mesurer ce qu'il est censé mesurer","Fournir une information cohérente","Détecter des changements au fil du temps","Être compris par le patient"],"r":2,"e":"C'est une qualité décisive en rééducation : un instrument valide et fiable mais peu réactif ne permettra pas de suivre les progrès d'un patient.","s":5},{"q":"L'alpha de Cronbach est considéré comme satisfaisant à partir de :","o":["0,5","0,6","0,7","0,9"],"r":2,"e":"Ses valeurs s'échelonnent de 0 à 0,95. Il mesure la cohérence interne, c'est-à-dire la concordance entre les items censés évaluer le même construit.","s":5},{"q":"La fiabilité test-retest évalue :","o":["La concordance entre observateurs","La stabilité intertemporelle des mesures","La cohérence entre items","L'erreur de mesure absolue"],"r":1,"e":"Les autres formes de fiabilité sont la cohérence interne, la fiabilité inter et intra-observateurs, et l'erreur de mesure.","s":5},{"q":"La spécificité d'un test se définit comme sa capacité à :","o":["Identifier correctement les individus qui présentent la maladie","Identifier correctement ceux qui ne la présentent pas","Détecter les changements dans le temps","Mesurer plusieurs construits"],"r":1,"e":"La sensibilité est l'inverse : identifier correctement ceux qui ont la maladie. Un test très sensible sert à écarter, un test très spécifique à confirmer.","s":5},{"q":"L'adaptation transculturelle selon Beaton et al. (2000) comporte :","o":["4 étapes","6 étapes","8 étapes","10 étapes"],"r":1,"e":"Traduction par deux traducteurs, synthèse, rétrotraduction par deux autres, comité d'experts, pré-test sur 30 à 40 participants, puis envoi du matériel aux auteurs originaux.","s":5},{"q":"Le pré-test de l'adaptation transculturelle porte sur :","o":["10 participants","20 participants","30 à 40 participants","100 participants"],"r":2,"e":"Il vise à vérifier la compréhension effective des items dans la langue cible, avant toute étude psychométrique de validation.","s":5},{"q":"Les trois critères obligatoires de l'adaptation transculturelle sont :","o":["Équivalence conceptuelle, équivalence sémantique et propriétés psychométriques","Traduction, rétrotraduction et pré-test","Validité, fiabilité et réactivité","Sensibilité, spécificité et précision"],"r":0,"e":"Le cours rappelle en outre la nécessité d'obtenir l'autorisation d'utilisation auprès des auteurs de l'instrument original.","s":5},{"q":"Les Core Outcome Sets correspondent à :","o":["L'ensemble des instruments validés dans un domaine","Un ensemble minimal de domaines de résultats fondamentaux, à mesurer dans les études de recherche","Les recommandations cliniques","Les critères d'inclusion d'une revue"],"r":1,"e":"Les initiatives COMET et ICHOM les développent. Leur intérêt est de rendre les études comparables entre elles en harmonisant ce qui est mesuré.","s":5},{"q":"La citation de Jules Rothstein (1995) rapportée par le cours affirme que la kinésithérapie :","o":["Est une science exacte","Restera toujours en partie un art, mais que sans mesure elle ne serait rien de plus qu'un art","Doit renoncer à la mesure","Est identique à la médecine"],"r":1,"e":"La formule articule les deux versants : la mesure ne supprime pas la dimension d'art, elle l'empêche de rester sans fondement vérifiable.","s":5},{"q":"L'évaluation, distinguée de la mesure, se définit comme :","o":["La quantification de caractéristiques déterminées","Le processus de sélection, recueil, analyse et interprétation d'information clinique subjective et objective","Le calcul d'un score","La comparaison à une norme"],"r":1,"e":"La mesure est un acte technique ; l'évaluation, un processus de raisonnement qui englobe le choix de ce qui est mesuré et l'interprétation du résultat.","s":5},{"q":"Le SF-36 est cité comme exemple d'instrument :","o":["Générique","Spécifique d'une région du corps","Spécifique de signes et symptômes","Spécifique d'une population"],"r":0,"e":"Il figure également parmi les exemples de PROM, aux côtés de l'EuroQol EQ-5D, ce qui illustre le recoupement entre les deux classifications.","s":5},{"q":"Les modèles conceptuels servant à identifier les résultats à mesurer incluent notamment :","o":["La CIF","Le modèle biomédical","La pyramide de l'évidence","GRADE"],"r":0,"e":"S'y ajoutent les modèles endpoint, spécifiques par pathologie, et les Core Outcome Sets développés par COMET et ICHOM.","s":5},{"q":"L'erreur de mesure est classée dans le cours parmi :","o":["Les types de validité","Les types de fiabilité","Les types de réactivité","Les critères de sensibilité"],"r":1,"e":"Elle rejoint la cohérence interne, le test-retest et la fiabilité inter et intra-observateurs, qui explorent tous la constance de l'information produite.","s":5},{"q":"Un instrument spécifique d'une population se distingue d'un instrument spécifique d'une condition parce qu'il cible :","o":["Un groupe défini par l'âge ou le statut plutôt qu'une pathologie","Une région anatomique","Un symptôme isolé","Un domaine conceptuel"],"r":0,"e":"Les six types recensés couvrent les instruments génériques, spécifiques d'une condition, d'une population, de signes et symptômes, d'une région du corps et d'un domaine.","s":5},{"q":"Selon l'ordre d'importance donné par le cours, le premier critère psychométrique à considérer est :","o":["La consistance interne","La validité de contenu","La réactivité","La fiabilité test-retest"],"r":1,"e":"Un instrument qui ne couvre pas correctement le construit ne peut être rattrapé par aucune autre qualité : la validité de contenu conditionne tout le reste.","s":5},{"q":"Que représente la partie visible de l'iceberg dans le modèle iceberg en santé ?","o":["L'évidence clinique présentée, c'est-à-dire la pyramide de l'évidence","Les biais de publication","L'expertise du clinicien","Les préférences du patient"],"r":0,"e":"La partie visible représente l'évidence clinique présentée — la pyramide de l'évidence ; la partie immergée correspond aux aspects cachés de l'évidence clinique.","s":6},{"q":"Que souligne le modèle iceberg ?","o":["Que la PBE suffit à elle seule","L'importance d'une approche plus approfondie des données : au-delà de la PBE, il existe plus d'informations pertinentes","Que la pyramide doit être abandonnée","Que seule la méta-analyse compte"],"r":1,"e":"Le modèle souligne l'importance d'une approche plus approfondie des données : au-delà de la PBE, il existe plus d'informations pertinentes pour comprendre les résultats en santé.","s":6},{"q":"Que se passe-t-il à mesure qu'on monte dans la pyramide de l'évidence ?","o":["Plus de littérature disponible et moins de pertinence","Moins de littérature disponible et plus de littérature pertinente pour la pratique clinique","Plus de littérature disponible et plus de pertinence","Aucun changement"],"r":1,"e":"En montant dans la pyramide, on a moins de littérature disponible mais plus de littérature pertinente pour la pratique clinique.","s":6},{"q":"Comment Sackett (2000) définit-il la pratique fondée sur l'évidence ?","o":["L'application stricte des essais randomisés","L'intégration de la meilleure évidence disponible avec l'expertise clinique et avec les valeurs du patient","La consultation systématique des guidelines","La recherche de consensus entre experts"],"r":1,"e":"Selon Sackett (2000), la PBE est l'intégration de la meilleure évidence disponible avec l'expertise clinique et avec les valeurs du patient.","s":6},{"q":"Quelles sont les cinq étapes de la PBE ?","o":["Poser une question, trouver la meilleure évidence, évaluer l'évidence, appliquer l'information, évaluer les outcomes","Lire, résumer, appliquer, publier, réviser","Diagnostiquer, traiter, évaluer, adapter, conclure","Chercher, sélectionner, extraire, analyser, conclure"],"r":0,"e":"Les cinq étapes sont : poser une question, trouver la meilleure évidence, évaluer l'évidence, appliquer l'information et évaluer les outcomes.","s":6},{"q":"Qui peut chercher l'évidence selon le cours ?","o":["Uniquement le professionnel","Le professionnel, mais aussi le patient s'il le souhaite, en étant orienté par le professionnel","Uniquement un documentaliste","Uniquement un chercheur universitaire"],"r":1,"e":"Le professionnel fait une recherche, mais le patient peut aussi le faire s'il le souhaite, en étant orienté par le professionnel.","s":6},{"q":"Comment se prend la décision à l'étape « appliquer l'information » ?","o":["Le professionnel décide seul selon les guidelines","Le patient discute avec le professionnel, qui informe sur les risques et bénéfices, et ils décident ensemble selon les valeurs et préférences du patient","Le patient décide seul","La décision suit automatiquement le niveau de preuve"],"r":1,"e":"Le patient discute avec le professionnel de la meilleure option, le professionnel informe sur les risques et bénéfices, et ensemble ils décident selon les valeurs et préférences du patient.","s":6},{"q":"Quel principe justifie la hiérarchie de l'évidence ?","o":["L'évidence n'est pas toute égale ni valide","Toutes les études se valent","Seuls les experts jugent la qualité","La littérature récente est toujours meilleure"],"r":0,"e":"L'évidence n'est pas toute égale ni valide : la hiérarchie de l'évidence guide la décision clinique en graduant la force de l'évidence.","s":6},{"q":"Pourquoi l'évidence seule ne suffit-elle jamais ?","o":["Parce qu'elle est toujours fausse","Parce que les professionnels doivent utiliser leur expérience pour identifier rapidement la situation clinique de chaque patient","Parce qu'elle est trop coûteuse à obtenir","Parce qu'elle est difficile à lire"],"r":1,"e":"L'évidence à elle seule ne sera jamais suffisante : les professionnels doivent utiliser leur expérience pour identifier rapidement la situation clinique de chaque patient.","s":6},{"q":"Quel est le principe central de la pratique informée par l'évidence ?","o":["Utiliser l'évidence comme orientation pour la prise de décisions, sans en dépendre exclusivement","Suivre strictement les guidelines","Ignorer la recherche scientifique","Ne se fier qu'à l'expérience clinique"],"r":0,"e":"La PIE utilise l'évidence scientifique comme une orientation pour la prise de décisions, mais sans en dépendre exclusivement.","s":6},{"q":"Que reconnaît la pratique informée par l'évidence ?","o":["Que la recherche est toujours applicable","Qu'il n'est pas toujours possible ou nécessaire de suivre strictement les directives de la PBE, surtout quand la recherche est limitée ou non concluante","Que les guidelines sont inutiles","Que l'expérience clinique doit primer systématiquement"],"r":1,"e":"La PIE reconnaît qu'il n'est pas toujours possible ou nécessaire de suivre strictement les directives de la PBE, en particulier là où la recherche est limitée, non concluante ou non directement applicable.","s":6},{"q":"Qu'est-ce que la PIE valorise ?","o":["La rigueur statistique","L'applicabilité et l'adaptabilité","L'uniformité des protocoles","La quantité de publications"],"r":1,"e":"La PIE valorise l'applicabilité et l'adaptabilité, reconnaissant que la science ne fournit pas toujours de réponses toutes faites pour tous les contextes.","s":6},{"q":"Comment l'APTA définit-elle la pratique kinésithérapique fondée sur les preuves ?","o":["Une application mécanique des données probantes","Une prise de décision clinique ouverte et réfléchie intégrant les meilleures données disponibles, le jugement clinique, les préférences du patient et le contexte social","Un protocole standardisé de soins","Une recherche bibliographique préalable à chaque séance"],"r":1,"e":"L'EBPP est une « prise de décision clinique ouverte et réfléchie » intégrant les meilleures données disponibles avec le jugement clinique, les préférences et valeurs du patient, et tenant compte du contexte social plus large.","s":6},{"q":"Quel est l'objectif de l'EBPP selon l'APTA ?","o":["Réduire les coûts de santé","Optimiser les résultats et la qualité de vie du patient","Uniformiser les pratiques professionnelles","Augmenter le nombre de publications"],"r":1,"e":"L'EBPP vise à optimiser les résultats et la qualité de vie du patient.","s":6},{"q":"Que déclare la WCPT en 2001 concernant les décisions en kinésithérapie ?","o":["Elles doivent être fondées sur l'expérience du praticien","Elles doivent être fondées sur des études aux méthodologies rigoureuses dont l'évidence est acceptée comme valide par la communauté scientifique","Elles doivent suivre les protocoles institutionnels","Elles doivent être validées par le patient uniquement"],"r":1,"e":"Selon la WCPT (2001), les décisions en kinésithérapie doivent être fondées sur des études présentant des résultats étayés par des méthodologies rigoureuses et dont l'évidence est acceptée comme valide par la communauté scientifique.","s":6},{"q":"À quoi correspond le Type I d'évidence selon Cochrane (2004) ?","o":["Évidence forte d'au moins une revue systématique ou d'un ECR bien conçu","Un ECR de taille adéquate","Une étude de cohorte","Une opinion d'expert"],"r":0,"e":"Le Type I correspond à une évidence forte provenant d'au moins une revue systématique ou d'un ECR bien conçu.","s":6},{"q":"À quoi correspond le Type III d'évidence ?","o":["À une méta-analyse","À des études bien conçues mais sans randomisation : cohorte, cas-témoins, transversales","À des opinions d'autorités respectées","À un ECR de grande taille"],"r":1,"e":"Le Type III correspond à l'évidence provenant d'études bien conçues mais sans randomisation : études de cohorte, cas-témoins et transversales.","s":6},{"q":"À quoi correspond le Type V d'évidence ?","o":["Aux études non expérimentales multicentriques","Aux opinions d'autorités respectées, études descriptives ou rapports de comités d'experts","Aux revues systématiques","Aux essais randomisés"],"r":1,"e":"Le Type V regroupe les opinions d'autorités respectées fondées sur l'évidence clinique, les études descriptives ou les rapports de comités d'« experts ».","s":6},{"q":"Comment le cours décrit-il, avec humour, le Type VI d'évidence ?","o":["« Un collègue l'a essayé »","« Quelqu'un me l'a dit une fois »","« C'est dans un livre »","« C'est logique »"],"r":1,"e":"Le Type VI, dernier niveau de la classification Cochrane 2004 présentée, est formulé « Quelqu'un me l'a dit une fois ».","s":6},{"q":"Quelle est la différence entre les types IV et V d'évidence ?","o":["Le type IV provient d'études non expérimentales bien conçues de plus d'un centre, le type V d'opinions d'autorités et d'études descriptives","Le type IV est plus faible que le type V","Le type IV concerne les essais randomisés","Il n'y a aucune différence"],"r":0,"e":"Le type IV provient d'études non expérimentales bien conçues, de plus d'un centre ou groupe de recherche ; le type V regroupe opinions d'autorités, études descriptives et rapports de comités d'experts.","s":6},{"q":"Que signifie un grade de recommandation A ?","o":["Faible évidence","Évidence suffisante","Évidence forte soutenant que l'intervention doit être considérée","Études incohérentes"],"r":2,"e":"Le grade A correspond à une évidence forte qui soutient la recommandation que l'intervention doit être considérée.","s":6},{"q":"Que signifie un grade de recommandation D ?","o":["Évidence forte contre l'intervention","Études incohérentes et non concluantes","Faible évidence mais recommandation possible","Évidence suffisante"],"r":1,"e":"Le grade D correspond à des études incohérentes et non concluantes.","s":6},{"q":"Que signifie un grade de recommandation C ?","o":["Faible évidence soutenant l'inclusion ou l'exclusion de l'intervention, mais des recommandations peuvent être faites dans d'autres domaines","Évidence forte","Absence totale d'études","Contre-indication formelle"],"r":0,"e":"Le grade C correspond à une faible évidence soutenant l'inclusion ou l'exclusion de l'intervention, mais des recommandations peuvent être faites dans d'autres domaines.","s":6},{"q":"Selon la classification JAMA (2000), sur quoi repose le niveau 1 ?","o":["Des rapports de cas","Des études prospectives non randomisées","Des essais cliniques randomisés ou une méta-analyse d'essais cliniques","L'opinion de spécialistes"],"r":2,"e":"Le niveau 1 du JAMA repose sur des essais cliniques randomisés ou une méta-analyse d'essais cliniques : action fortement recommandée.","s":6},{"q":"Selon la classification JAMA, que conclut-on d'un niveau 3 ?","o":["Action fortement recommandée","Action recommandée","Action peu recommandée","Action contre-indiquée"],"r":2,"e":"Le niveau 3 repose sur des rapports de cas ou l'opinion de spécialistes : l'action est peu recommandée.","s":6},{"q":"Sur quoi repose le niveau 2 de la classification JAMA ?","o":["Des essais randomisés","Des études prospectives non randomisées","Des méta-analyses","Des séries de cas"],"r":1,"e":"Le niveau 2 repose sur des études prospectives non randomisées : action recommandée.","s":6},{"q":"Quel outil est présenté comme le plus adopté pour classer la qualité de l'évidence ?","o":["GRADE","PRISMA","AMSTAR","CONSORT"],"r":0,"e":"GRADE est l'outil le plus adopté pour classer la qualité de l'évidence et formuler les recommandations.","s":6},{"q":"Quelle priorité de recherche arrive en tête chez les kinésithérapeutes portugais et les patients ?","o":["Le coût-efficacité","Le développement professionnel","La qualité","La prestation de services"],"r":0,"e":"Parmi les 10 priorités les plus consensuelles figurent, dans l'ordre présenté : coût-efficacité, prestation de services et éducation, développement professionnel, qualité.","s":6},{"q":"Quel épisode historique a conduit Archie Cochrane à réaliser ce que le cours décrit comme le premier essai clinique ?","o":["Une épidémie de grippe à l'hôpital","Sa captivité comme prisonnier de guerre, où il a comparé vitamine D et vitamine C chez des prisonniers œdémateux","Une étude sur l'aspirine après infarctus","Une enquête sur la tuberculose"],"r":1,"e":"Prisonnier de guerre, il a observé des œdèmes des membres inférieurs qu'il attribuait à une carence vitaminique, et a comparé deux groupes de prisonniers, l'un recevant de la vitamine D, l'autre de la vitamine C.","s":6},{"q":"Quel est l'objectif de la recherche dans la pratique clinique du kinésithérapeute selon le cours ?","o":["Remplacer le raisonnement clinique","Servir d'adjuvant à l'intervention et aider à sélectionner la meilleure évidence pour la planification et la prise de décisions","Justifier a posteriori les traitements choisis","Satisfaire aux obligations universitaires"],"r":1,"e":"Il s'agit de rechercher dans la pratique clinique comme adjuvant à l'intervention du kinésithérapeute, et de sélectionner la meilleure évidence clinique pour collaborer à la planification et à la prise de décisions.","s":6},{"q":"Dans le modèle iceberg en santé, la partie visible correspond :","o":["Aux aspects cachés de l'évidence","À l'évidence clinique présentée, c'est-à-dire la pyramide de l'évidence","Aux préférences du patient","Au coût des interventions"],"r":1,"e":"Le modèle rappelle qu'au-delà de la PBE, il existe davantage d'informations pertinentes pour comprendre les résultats en santé.","s":6},{"q":"En montant dans la pyramide de l'évidence :","o":["La littérature disponible augmente et sa pertinence diminue","La littérature disponible diminue et sa pertinence pour la pratique clinique augmente","Les deux augmentent","Les deux diminuent"],"r":1,"e":"Les revues systématiques et méta-analyses sont rares mais directement exploitables ; les études primaires sont nombreuses mais exigent un travail d'interprétation.","s":6},{"q":"La définition de la PBE par Sackett (2000) intègre :","o":["La meilleure évidence disponible, l'expertise clinique et les valeurs du patient","Les preuves et les recommandations officielles","L'expérience du praticien uniquement","Le rapport coût-efficacité"],"r":0,"e":"Ces trois composantes sont indissociables : retirer l'une d'elles fait sortir du cadre de la pratique fondée sur l'évidence.","s":6},{"q":"La deuxième des cinq étapes de la PBE consiste à :","o":["Poser une question","Trouver la meilleure évidence","Évaluer l'évidence","Appliquer l'information"],"r":1,"e":"La séquence complète : poser une question, trouver la meilleure évidence, l'évaluer, appliquer l'information, puis évaluer les outcomes.","s":6},{"q":"La cinquième étape de la PBE consiste à :","o":["Publier les résultats","Évaluer les outcomes","Rechercher de nouvelles preuves","Former les collègues"],"r":1,"e":"Cette dernière étape referme la boucle : sans évaluation du résultat obtenu chez ce patient, l'application de la preuve reste un pari non vérifié.","s":6},{"q":"Le deuxième principe de la PBE énonce que :","o":["Toute évidence se vaut","L'évidence seule ne sera jamais suffisante, l'expérience du professionnel identifiant la situation clinique","L'expérience prime sur les preuves","Les préférences du patient sont secondaires"],"r":1,"e":"Le premier principe pose que l'évidence n'est ni toute égale ni toute valide, d'où la hiérarchie ; le troisième impose d'appliquer selon le rapport risques/bénéfices pour chaque patient.","s":6},{"q":"La pratique informée par l'évidence (PIE) se distingue en ce qu'elle :","o":["Rejette les preuves scientifiques","Utilise l'évidence comme orientation sans en dépendre exclusivement, en l'adaptant au contexte, à l'expérience et aux besoins du patient","Suit strictement les guidelines","Se fonde sur l'opinion d'experts"],"r":1,"e":"Elle valorise l'applicabilité et l'adaptabilité, et reconnaît que la science, outil puissant, ne fournit pas toujours de réponses toutes faites pour tous les contextes.","s":6},{"q":"L'EBPP défini par l'APTA est décrit comme :","o":["Une application mécanique des protocoles","Une prise de décision clinique ouverte et réfléchie intégrant preuves, jugement clinique et préférences du patient, en tenant compte du contexte social","Un algorithme décisionnel","Une démarche exclusivement scientifique"],"r":1,"e":"L'objectif affiché est d'optimiser les résultats et la qualité de vie. La mention du contexte social élargit le cadre au-delà du colloque singulier.","s":6},{"q":"Selon la classification Cochrane (2004), le type d'évidence I correspond :","o":["À une revue systématique ou à un essai contrôlé randomisé bien conçu","À un ECR de taille adéquate","À une étude de cohorte","À l'opinion d'experts"],"r":0,"e":"Le type II correspond à un ECR bien conçu et de taille adéquate, le type III aux études bien conçues sans randomisation.","s":6},{"q":"Le type d'évidence V de la classification Cochrane regroupe :","o":["Les études non expérimentales multicentriques","Les opinions d'autorités respectées, les études descriptives et les rapports de comités d'experts","Les essais randomisés de petite taille","Les revues systématiques"],"r":1,"e":"Le type VI, dernier de l'échelle, est formulé avec humour par le cours : « quelqu'un me l'a dit une fois ».","s":6},{"q":"Le type d'évidence IV correspond :","o":["Aux études non expérimentales bien conçues, provenant de plus d'un centre","Aux essais randomisés","Aux revues systématiques","Aux opinions d'experts"],"r":0,"e":"Le caractère multicentrique renforce la crédibilité en réduisant le risque qu'un résultat tienne aux particularités d'un seul lieu.","s":6},{"q":"Le grade de recommandation B correspond à :","o":["Une évidence forte","Une évidence suffisante","Une faible évidence","Des études incohérentes et non concluantes"],"r":1,"e":"Le grade A correspond à une évidence forte, le C à une faible évidence, le D à des études incohérentes et non concluantes.","s":6},{"q":"Selon la classification JAMA (2000), le niveau 2 correspond :","o":["À un ECR ou une méta-analyse, action fortement recommandée","À des études prospectives non randomisées, action recommandée","À des rapports de cas, action peu recommandée","À l'opinion de spécialistes"],"r":1,"e":"Le niveau 1 réunit ECR et méta-analyses avec une action fortement recommandée ; le niveau 3 les rapports de cas et opinions de spécialistes, peu recommandés.","s":6},{"q":"L'exemple du cours sur le choix entre comprimés et injections de morphine en post-opératoire illustre :","o":["Une question de coût","L'application concrète de la PBE à une décision de traitement","Un problème de diagnostic","Une question éthique"],"r":1,"e":"Il met en scène les trois composantes : ce que disent les données, ce que sait le clinicien de cette situation, et ce que le patient préfère.","s":6},{"q":"La pyramide de l'évidence a pour fonction :","o":["De classer les patients","De servir de ligne directrice pour hiérarchiser l'évidence disponible","De remplacer le jugement clinique","De mesurer les résultats"],"r":1,"e":"Elle ordonne les sources selon leur capacité à limiter les biais, sans pour autant dispenser d'évaluer la qualité de chaque étude prise isolément.","s":6},{"q":"Le premier principe de la PBE affirme que :","o":["Toutes les preuves ont la même valeur","L'évidence n'est ni toute égale ni toute valide, d'où la nécessité d'une hiérarchie","Les preuves suffisent à décider","Seules les méta-analyses comptent"],"r":1,"e":"C'est ce qui justifie l'existence même de la pyramide et des outils d'évaluation du risque de biais comme GRADE.","s":6},{"q":"La pratique informée par l'évidence reconnaît explicitement que la science :","o":["Fournit toujours des réponses applicables","Est un outil puissant mais ne fournit pas toujours de réponses toutes faites pour tous les contextes","Doit être écartée en clinique","Se limite aux essais randomisés"],"r":1,"e":"Cette reconnaissance n'est pas un relativisme : elle justifie l'adaptation au contexte là où les données manquent ou ne couvrent pas la situation.","s":6},{"q":"Le troisième principe de la PBE impose d'appliquer l'évidence :","o":["De façon identique à tous les patients","Selon le rapport risques/bénéfices propre à chaque patient","Uniquement si elle est de grade A","Après accord de l'équipe"],"r":1,"e":"Une même intervention peut être justifiée chez l'un et déraisonnable chez l'autre, selon les comorbidités, l'âge ou les priorités de la personne.","s":6},{"q":"Le grade de recommandation D correspond à :","o":["Une évidence forte","Une évidence suffisante","Une faible évidence","Des études incohérentes et non concluantes"],"r":3,"e":"Il ne signifie pas que l'intervention est inefficace, mais que l'état des données ne permet pas de trancher — ce qui appelle prudence et réévaluation.","s":6},{"q":"Selon JAMA (2000), le niveau 3 regroupe :","o":["Les essais randomisés","Les études prospectives non randomisées","Les rapports de cas ou l'opinion de spécialistes, avec une action peu recommandée","Les méta-analyses"],"r":2,"e":"Ces sources gardent une utilité pour les situations rares, où aucune étude de niveau supérieur n'existe ni ne pourra raisonnablement exister.","s":6},{"q":"Comment le cours définit-il la statistique ?","o":["La science du recueil et de l'analyse des données, pour inférer d'un échantillon à la population et prédire l'évolution d'un phénomène","La description chiffrée d'une population","Le calcul des probabilités","La représentation graphique des données"],"r":0,"e":"La statistique est la science du recueil et de l'analyse des données, dans le but d'utiliser les probabilités pour inférer d'un échantillon à la population et prédire l'évolution future d'un phénomène.","s":7},{"q":"Qu'est-ce que la biostatistique ?","o":["L'étude des populations animales","Les statistiques appliquées aux phénomènes biologiques et liés à la santé","La biologie quantitative","L'analyse des essais cliniques uniquement"],"r":1,"e":"La biostatistique correspond aux statistiques appliquées aux phénomènes biologiques et liés à la santé.","s":7},{"q":"Lequel de ces éléments N'EST PAS un objectif de l'échantillonnage ?","o":["Coût moindre","Travail de terrain réduit","Meilleure précision et validité","Étude exhaustive de tous les éléments de la population"],"r":3,"e":"Les objectifs de l'échantillonnage sont un coût moindre, un travail de terrain réduit, une meilleure précision/validité et des méthodes optimisées.","s":7},{"q":"Qu'est-ce qu'un paramètre en statistique ?","o":["Une caractéristique numérique d'une population, fixe et inconnue","Une valeur calculée à partir de l'échantillon","Une fonction de l'échantillon","La valeur observée d'un individu"],"r":0,"e":"Le paramètre est la caractéristique numérique d'une population, fixe et inconnue : µ, σ², σ, p.","s":7},{"q":"Qu'est-ce qu'un estimateur ?","o":["Un paramètre de la population","Une fonction de l'échantillon, c'est-à-dire une variable aléatoire","La valeur numérique observée","Une constante"],"r":1,"e":"L'estimateur est une fonction de l'échantillon — une variable aléatoire — notée X̄, S², S, p̂.","s":7},{"q":"Quelle est la différence entre estimateur et estimation ?","o":["L'estimateur est la fonction de l'échantillon, l'estimation est sa valeur numérique observée","L'estimateur est une valeur, l'estimation une fonction","Ce sont des synonymes","L'estimation concerne la population"],"r":0,"e":"L'estimateur est une fonction de l'échantillon (variable aléatoire) ; l'estimation est l'observation numérique de cet estimateur, par exemple p̂ = 0,63.","s":7},{"q":"Quels symboles désignent les paramètres de population ?","o":["X̄, S², S, p̂","x̄, s², s, p̂","µ, σ², σ, p","xi, yi, zi"],"r":2,"e":"Les paramètres de population sont notés µ, σ², σ et p ; les estimateurs X̄, S², S, p̂ et les estimations x̄, s², s, p̂.","s":7},{"q":"Par quoi divise-t-on pour calculer la variance d'un ÉCHANTILLON ?","o":["Par N","Par n","Par n − 1","Par n + 1"],"r":2,"e":"La variance de l'échantillon s'écrit s² = 1/(n − 1) · Σ(xᵢ − x̄)², tandis que la variance de la population divise par N.","s":7},{"q":"Quelle est la moyenne de l'échantillon 3, 7, 8, 10, 11 ?","o":["7,0","7,8","8,0","8,5"],"r":1,"e":"x̄ = (3 + 7 + 8 + 10 + 11)/5 = 7,8.","s":7},{"q":"Quelle est la variance de l'échantillon 3, 7, 8, 10, 11 ?","o":["11,76","14,70","18,37","7,80"],"r":1,"e":"s² = [(3−7,8)² + (7−7,8)² + (8−7,8)² + (10−7,8)² + (11−7,8)²]/4 = 14,70.","s":7},{"q":"Dans un échantillon de 10 individus dont 4 possèdent la caractéristique d'intérêt, quelle est la proportion estimée ?","o":["0,04","0,25","0,4","4"],"r":2,"e":"p̂ = x/n = 4/10 = 0,4.","s":7},{"q":"Quel type de variable est le nombre d'enfants ?","o":["Quantitative continue","Quantitative discrète","Qualitative nominale","Qualitative ordinale"],"r":1,"e":"Le nombre d'enfants est une variable quantitative discrète : elle représente un comptage en valeurs entières.","s":7},{"q":"Quel type de variable est le poids ?","o":["Quantitative continue","Quantitative discrète","Qualitative nominale","Qualitative ordinale"],"r":0,"e":"Le poids, comme la taille et l'âge, est une variable quantitative continue : c'est une mesure pouvant prendre toute valeur dans un intervalle.","s":7},{"q":"Quel type de variable est le groupe sanguin ?","o":["Quantitative discrète","Qualitative nominale","Qualitative ordinale","Quantitative continue"],"r":1,"e":"Le groupe sanguin, comme le sexe, est une variable qualitative nominale : les valeurs représentent des caractéristiques sans ordre inhérent.","s":7},{"q":"Quel type de variable est la catégorie d'IMC ?","o":["Qualitative nominale","Qualitative ordinale","Quantitative continue","Quantitative discrète"],"r":1,"e":"Les catégories de classification de l'IMC, comme le niveau d'études, sont des variables qualitatives ordinales : elles ont un ordre logique et séquentiel.","s":7},{"q":"Quelle statistique utilise-t-on pour la moyenne d'une population normale avec σ INCONNU ?","o":["Z, loi normale centrée réduite","T, loi de Student à n − 1 degrés de liberté","F, loi de Fisher","Le khi-deux"],"r":1,"e":"Avec σ inconnu et une population normale, T = (X̄ − µ)/(S/√n) suit une loi de Student à n − 1 degrés de liberté.","s":7},{"q":"Quel théorème justifie l'usage de Z pour les grands échantillons ?","o":["Le théorème de Bayes","Le Théorème Central Limite","Le théorème de Student","La loi des grands nombres de Fisher"],"r":1,"e":"Pour un grand échantillon (n ≥ 30), le Théorème Central Limite permet d'utiliser Z = (X̄ − µ)/(S/√n) ~ N(0, 1).","s":7},{"q":"À partir de quelle taille d'échantillon le cours applique-t-il le TCL pour la moyenne ?","o":["n ≥ 10","n ≥ 20","n ≥ 30","n ≥ 100"],"r":2,"e":"Le cours retient n ≥ 30 comme seuil de grand échantillon pour appliquer le Théorème Central Limite.","s":7},{"q":"Quel est l'intervalle de confiance pour µ quand σ est connu ?","o":["X̄ ± z(1−α/2) · σ/√n","X̄ ± t(1−α/2, n−1) · S/√n","p̂ ± z(1−α/2) · √[p̂(1−p̂)/n]","X̄ ± σ"],"r":0,"e":"Avec σ connu et une population normale, l'intervalle de confiance est X̄ ± z(1−α/2) · σ/√n.","s":7},{"q":"Quel est l'intervalle de confiance pour une proportion (n > 30) ?","o":["p̂ ± z(1−α/2) · σ/√n","p̂ ± z(1−α/2) · √[p̂(1 − p̂)/n]","p̂ ± t(1−α/2, n−1) · S/√n","p̂ ± p̂/n"],"r":1,"e":"Pour n > 30, l'intervalle de confiance de la proportion est p̂ ± z(1−α/2) · √[p̂(1 − p̂)/n].","s":7},{"q":"Comment s'écrit l'hypothèse nulle d'un test sur la moyenne ?","o":["H0 : µ ≠ µ0","H0 : µ = µ0","H0 : µ > µ0","H0 : µ < µ0"],"r":1,"e":"L'hypothèse nulle s'écrit H0 : µ = µ0 ; l'alternative peut être bilatérale (µ ≠ µ0), unilatérale droite (µ > µ0) ou gauche (µ < µ0).","s":7},{"q":"Quelle est la règle de rejet d'un test BILATÉRAL avec la statistique Z ?","o":["Rejeter H0 si Z > z(1−α)","Rejeter H0 si |Z| > z(1−α/2)","Rejeter H0 si Z < −z(1−α)","Rejeter H0 si Z = 0"],"r":1,"e":"Pour un test bilatéral, on rejette H0 si |Z| > z(1−α/2) ; pour un unilatéral droit si Z > z(1−α) et gauche si Z < −z(1−α).","s":7},{"q":"Quelle statistique utilise-t-on pour deux échantillons indépendants, variances inconnues mais ÉGALES ?","o":["Z avec les variances de population","T avec variance combinée (pooled), à n1 + n2 − 2 degrés de liberté","T de Welch","F de Fisher"],"r":1,"e":"Avec des variances inconnues mais égales, on utilise la variance combinée Sp² et un T à n1 + n2 − 2 degrés de liberté.","s":7},{"q":"Comment se calcule la variance combinée (pooled) ?","o":["[(n1−1)S1² + (n2−1)S2²] / (n1 + n2 − 2)","(S1² + S2²) / 2","S1²/n1 + S2²/n2","(n1 S1² + n2 S2²) / (n1 + n2)"],"r":0,"e":"La variance combinée est Sp² = [(n1 − 1)S1² + (n2 − 1)S2²] / (n1 + n2 − 2).","s":7},{"q":"Quel test utilise-t-on quand les variances sont inconnues et DIFFÉRENTES ?","o":["Le test Z","Le test T de Welch, avec des degrés de liberté approchés","Le test F","Le test apparié"],"r":1,"e":"Avec des variances inconnues et différentes, on utilise le T de Welch, dont les degrés de liberté ν sont approchés par une formule spécifique.","s":7},{"q":"Comment traite-t-on des échantillons appariés ?","o":["En comparant directement les deux moyennes","En définissant les différences Di = Xi − Yi puis en testant leur moyenne","En calculant la variance combinée","En appliquant le test F"],"r":1,"e":"Pour des observations appariées (échantillons dépendants), on définit les différences Di = Xi − Yi, puis on teste avec T (loi normale, variance inconnue) ou Z (n > 30).","s":7},{"q":"Quelle statistique sert au test d'égalité des variances ?","o":["Z","T","F = S1²/S2²","Le khi-deux"],"r":2,"e":"Le test d'égalité des variances utilise F = S1²/S2², qui suit une loi de Fisher à (n1 − 1, n2 − 1) degrés de liberté.","s":7},{"q":"Quelle loi suit la statistique F du test d'égalité des variances ?","o":["Une loi normale","Une loi de Student","Une loi de Fisher à (n1 − 1, n2 − 1) degrés de liberté","Une loi uniforme"],"r":2,"e":"F = S1²/S2² suit une loi de Fisher à n1 − 1 et n2 − 1 degrés de liberté.","s":7},{"q":"Quelle statistique utilise-t-on pour tester une proportion sur un grand échantillon ?","o":["Z","T","F","Le khi-deux"],"r":0,"e":"Le récapitulatif du cours indique la statistique Z pour le test de proportion sur grand échantillon.","s":7},{"q":"Quels logiciels le cours recommande-t-il ?","o":["Excel, SPSS et RStudio","MATLAB, Python et SAS","Stata, Minitab et JMP","Word, PowerPoint et Access"],"r":0,"e":"Les logiciels recommandés sont Excel, SPSS et RStudio.","s":7},{"q":"La biostatistique se définit comme :","o":["L'étude des probabilités pures","Les statistiques appliquées aux phénomènes biologiques et liés à la santé","La collecte de données hospitalières","L'analyse des essais cliniques uniquement"],"r":1,"e":"Le cours donne pour exemple l'effet d'un traitement sur l'échelle Activities-specific Balance Confidence. La statistique générale est, elle, la science du recueil et de l'analyse des données.","s":7},{"q":"Parmi les objectifs de l'échantillonnage, le cours cite :","o":["Un coût moindre, un travail de terrain réduit, une meilleure précision et des méthodes optimisées","L'exhaustivité","La rapidité de publication","La simplicité des calculs"],"r":0,"e":"Contre-intuitivement, bien échantillonner peut donner une meilleure précision qu'un recensement bâclé : mieux vaut mesurer soigneusement peu que mal beaucoup.","s":7},{"q":"Un paramètre statistique se caractérise comme :","o":["Une fonction de l'échantillon","Une caractéristique numérique de la population, fixe et inconnue","Une valeur numérique observée","Une variable aléatoire"],"r":1,"e":"Il se note µ, σ², σ, p. L'estimateur, noté X̄, S², S, p̂, est une fonction de l'échantillon, donc une variable aléatoire.","s":7},{"q":"L'estimation se distingue de l'estimateur parce qu'elle est :","o":["Une variable aléatoire","La valeur numérique observée à partir de l'échantillon","Un paramètre de population","Une hypothèse"],"r":1,"e":"On la note en minuscules : x̄, s², s, p̂. L'estimateur en majuscules désigne la règle de calcul, l'estimation son résultat sur un échantillon donné.","s":7},{"q":"Dans l'exemple de l'hémoglobine glyquée, µ désigne :","o":["La valeur observée chez un patient","La moyenne de la population","L'estimateur calculé sur l'échantillon","La caractéristique mesurée"],"r":1,"e":"X est la caractéristique, X̄ l'estimateur calculé à partir de l'échantillon, x̄ la valeur numérique observée, et xᵢ la valeur de chaque élément.","s":7},{"q":"Le nombre de médicaments pris par un patient est une variable :","o":["Quantitative discrète","Quantitative continue","Qualitative nominale","Qualitative ordinale"],"r":0,"e":"Les variables discrètes représentent des comptages en valeurs entières. Le poids, la taille et l'âge sont des variables continues.","s":7},{"q":"Le groupe sanguin est une variable :","o":["Quantitative discrète","Quantitative continue","Qualitative nominale","Qualitative ordinale"],"r":2,"e":"Les variables nominales n'ont pas d'ordre inhérent, à la différence des ordinales comme les catégories d'IMC ou le niveau d'études.","s":7},{"q":"Les catégories d'indice de masse corporelle constituent une variable :","o":["Quantitative continue","Qualitative nominale","Qualitative ordinale","Quantitative discrète"],"r":2,"e":"Elles possèdent un ordre logique et séquentiel, ce qui autorise certains traitements statistiques interdits aux variables nominales.","s":7},{"q":"La variance d'un échantillon se calcule en divisant par :","o":["n","n − 1","n + 1","N"],"r":1,"e":"C'est le piège classique signalé par le cours : la variance de la population se divise par N, celle de l'échantillon par n − 1.","s":7},{"q":"Pour l'échantillon 3, 7, 8, 10, 11, la moyenne vaut :","o":["7,0","7,8","8,0","8,2"],"r":1,"e":"La somme fait 39, divisée par 5 éléments. La variance correspondante, calculée avec n − 1 = 4 au dénominateur, vaut 14,70.","s":7},{"q":"Sur 10 individus dont 4 possèdent la caractéristique d'intérêt, la proportion estimée est :","o":["0,04","0,4","4","40"],"r":1,"e":"La proportion p̂ se calcule comme x/n. Elle s'exprime entre 0 et 1, et se convertit ensuite en pourcentage si besoin.","s":7},{"q":"Quand σ est connu et la population normale, l'inférence sur µ utilise :","o":["La loi normale centrée réduite Z","Le T de Student","La loi de Fisher","Le khi-deux"],"r":0,"e":"Si σ est inconnu et la population normale, on utilise le T de Student à n − 1 degrés de liberté ; pour n ≥ 30, le Z s'applique par le théorème central limite.","s":7},{"q":"Le théorème central limite permet d'utiliser la loi normale :","o":["Quel que soit l'effectif","Pour un grand échantillon, n ≥ 30, quelle que soit la loi d'origine","Uniquement si la population est normale","Uniquement pour les proportions"],"r":1,"e":"C'est ce qui rend les méthodes normales si largement applicables : la distribution de la moyenne tend vers la normale même si les données ne le sont pas.","s":7},{"q":"L'intervalle de confiance de la moyenne avec σ inconnu et population normale s'écrit :","o":["X̄ ± z · σ/√n","X̄ ± t(1−α/2, n−1) · S/√n","X̄ ± z · S/√n","p̂ ± z · √[p̂(1−p̂)/n]"],"r":1,"e":"La dernière formule est celle de l'intervalle de confiance d'une proportion, valable pour n supérieur à 30.","s":7},{"q":"Une hypothèse alternative unilatérale droite s'écrit :","o":["µ ≠ µ₀","µ > µ₀","µ < µ₀","µ = µ₀"],"r":1,"e":"H₀ pose toujours l'égalité µ = µ₀. L'alternative peut être bilatérale, unilatérale droite ou unilatérale gauche, selon la question posée.","s":7},{"q":"Pour comparer deux populations indépendantes à variances inconnues mais égales, on utilise :","o":["Un Z","Un T avec variance combinée, à n₁ + n₂ − 2 degrés de liberté","Le T de Welch","Une loi de Fisher"],"r":1,"e":"Si les variances sont inconnues et différentes, on recourt au T de Welch ; si elles sont connues ou les échantillons grands, au Z.","s":7},{"q":"Pour des échantillons appariés, la démarche consiste à :","o":["Comparer directement les deux moyennes","Définir les différences Dᵢ = Xᵢ − Yᵢ, puis appliquer un T ou un Z","Calculer une loi de Fisher","Utiliser un khi-deux"],"r":1,"e":"On se ramène ainsi à un problème à un seul échantillon : celui des différences. Le Z s'emploie si n dépasse 30.","s":7},{"q":"Le test d'égalité des variances utilise la statistique :","o":["F = S₁²/S₂², suivant une loi de Fisher","Z = (X̄ − µ)/(σ/√n)","T de Student","Le khi-deux d'ajustement"],"r":0,"e":"Ses degrés de liberté sont (n₁ − 1, n₂ − 1). Ce test conditionne le choix entre T à variance combinée et T de Welch.","s":7},{"q":"Parmi les logiciels recommandés par le cours figure :","o":["Excel, SPSS et RStudio","MATLAB uniquement","Photoshop","Access"],"r":0,"e":"Le choix dépend du niveau d'exigence : Excel pour les calculs simples, SPSS pour l'analyse clinique courante, RStudio pour les traitements avancés et reproductibles.","s":7},{"q":"L'écart-type s'obtient :","o":["En divisant la variance par n","En prenant la racine carrée de la variance","En multipliant la variance par n − 1","En sommant les écarts à la moyenne"],"r":1,"e":"Son intérêt est d'être exprimé dans la même unité que les données, contrairement à la variance qui est en unité au carré.","s":7}]};
